/**
 * scripts/audit_item_assets.ts
 *
 * ITEM ASSET IMAGE AUDITOR (Node.js 26+)
 * Compares src/data/items.ts entries against physical webp images in the public folder.
 * Categorizes and audits both Poké Market (Local Shop) and Battle Club (BC Shop) items.
 *
 * Usage: node --experimental-strip-types scripts/audit_item_assets.ts
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText, parseArgs } from 'node:util';
import { SHOP_ITEMS } from '../../src/data/inventory/items.ts';

const ITEM_MAPPING: Record<string, string> = {
  'pocion': 'potion',
  'super_pocion': 'super-potion',
  'hiper_pocion': 'hyper-potion',
  'pocion_max': 'max-potion',
  'revivir_max': 'max-revive',
  'quemadura': 'burn-heal',
  'despertar': 'awakening',
  'cura_total': 'full-heal',
  'elixir': 'ether',
  'elixir_max': 'max-elixir',
  'piedra_fuego': 'fire-stone',
  'piedra_agua': 'water-stone',
  'piedra_trueno': 'thunder-stone',
  'piedra_hoja': 'leaf-stone',
  'piedra_luna': 'moon-stone',
  'pokeball': 'poke-ball',
  'pokéball': 'poke-ball',
  'superball': 'great-ball',
  'greatball': 'great-ball',
  'super-ball': 'great-ball',
  'super ball': 'great-ball',
  'súper ball': 'great-ball',
  'ultraball': 'ultra-ball',
  'ultra-ball': 'ultra-ball',
  'ultra ball': 'ultra-ball',
  'masterball': 'master-ball',
  'master-ball': 'master-ball',
  'master ball': 'master-ball',
  'netball': 'net-ball',
  'net-ball': 'net-ball',
  'duskball': 'dusk-ball',
  'dusk-ball': 'dusk-ball',
  'turnoball': 'timer-ball',
  'timerball': 'timer-ball',
  'timer-ball': 'timer-ball',
  'turno ball': 'timer-ball',
  'repelente': 'repel',
  'super_repel': 'super-repel',
  'max_repel': 'max-repel',
  'huevo_suerte': 'lucky-egg',
  'huevo_suerte_pequeño': 'lucky-egg',
  'compartir_exp': 'exp-share',
  'restos': 'leftovers',
  'cascabel_concha': 'shell-bell',
  'cinta_elegida': 'choice-band',
  'banda_focus': 'focus-sash',
  'lente_zoom': 'scope-lens',
  'caramelo_raro': 'rare-candy',
  'subida_de_pp': 'pp-up',
  'moneda_amuleto': 'amulet-coin',
  'bola_luminosa': 'light-ball',
  'hueso_grueso': 'thick-club',
  'palo': 'stick',
  'polvo_metálico': 'metal-powder',
  'cuchara_torcida': 'twisted-spoon',
  'hechizo': 'spell-tag',
  'pesa_recia': 'power-weight',
  'brazal_recia': 'power-bracer',
  'cinto_recia': 'power-belt',
  'lente_recia': 'power-lens',
  'banda_recia': 'power-band',
  'franja_recia': 'power-anklet',
  'lazo_destino': 'destiny-knot',
  'piedra_eterna': 'everstone',
  'restaurador_vigor': 'rare-candy',
  'lemonade': 'lemonade',
  'refresco': 'soda-pop',
  'limonada': 'lemonade'
};

interface AuditResult {
  id: string;
  name: string;
  sprite: string;
  expectedPaths: string[];
  found: boolean;
  shops: string[];
}

async function main() {
  const { values } = parseArgs({
    options: {
      output: { type: 'string', short: 'o' },
      summary: { type: 'boolean', short: 's' }
    }
  });

  console.log(styleText('bold', '\n--- 🔎 ITEM IMAGE ASSETS AUDIT ---'));

  const publicDir = path.resolve(process.cwd(), 'public');
  const results: AuditResult[] = [];

  for (const item of SHOP_ITEMS) {
    if (!item.sprite) continue;

    const spriteId = item.sprite.replace(/\.(png|webp|jpg|jpeg|gif|bmp)$/i, '').toLowerCase();
    const mappedId = ITEM_MAPPING[spriteId] || spriteId.replace(/_/g, '-');

    const isPokeAPI = (ITEM_MAPPING[spriteId] !== undefined) || 
                     !isNaN(Number(spriteId)) || 
                     spriteId.includes('-') || 
                     spriteId.includes('ball') || 
                     spriteId.includes('stone') ||
                     spriteId.includes('repel') ||
                     spriteId.includes('fossil') ||
                     ['potion', 'revive', 'heal', 'ether', 'elixir', 'antidote', 'share', 'leftovers', 'bell', 'band', 'sash', 'lens', 'candy', 'up', 'egg', 'nugget', 'pearl', 'dust', 'piece', 'spoon', 'tag', 'powder', 'club', 'light', 'stick', 'ticket', 'radar', 'awakening'].some(k => mappedId.includes(k));

    const pathsToCheck: string[] = [];
    if (isPokeAPI) {
      pathsToCheck.push(path.join(publicDir, 'assets/sprites/items', `${mappedId}.webp`));
    } else {
      pathsToCheck.push(path.join(publicDir, 'assets/items', `${spriteId}.webp`));
    }

    let found = false;
    for (const p of pathsToCheck) {
      try {
        await fs.access(p);
        found = true;
        break;
      } catch {
        // Continue
      }
    }

    // Classify shops
    const shops: string[] = [];
    if (item.showInNormalShop !== false) {
      shops.push('Poké Market (Local)');
    }
    if (item.showInBCShop === true) {
      shops.push('BC Shop (Battle Club)');
    }

    results.push({
      id: item.id,
      name: item.name || item.id,
      sprite: item.sprite,
      expectedPaths: pathsToCheck,
      found,
      shops
    });
  }

  // Group and print stats
  const localShopItems = results.filter(r => r.shops.includes('Poké Market (Local)'));
  const bcShopItems = results.filter(r => r.shops.includes('BC Shop (Battle Club)'));

  const localFound = localShopItems.filter(r => r.found).length;
  const localMissing = localShopItems.filter(r => !r.found);

  const bcFound = bcShopItems.filter(r => r.found).length;
  const bcMissing = bcShopItems.filter(r => !r.found);

  console.log(`\n🏬 ${styleText('bold', 'POKÉ MARKET (TIENDA LOCAL):')}`);
  console.log(`   📦 Total ítems con sprite: ${localShopItems.length}`);
  console.log(`   ✅ Con imagen física:      ${localFound}`);
  console.log(`   ❌ Con imagen FALTANTE:    ${localMissing.length}`);

  console.log(`\n🎖️  ${styleText('bold', 'BATTLE CLUB SHOP (BC SHOP):')}`);
  console.log(`   📦 Total ítems con sprite: ${bcShopItems.length}`);
  console.log(`   ✅ Con imagen física:      ${bcFound}`);
  console.log(`   ❌ Con imagen FALTANTE:    ${bcMissing.length}`);

  console.log('\n════════════════════════════════════════════════');

  const allMissing = results.filter(r => !r.found);

  if (allMissing.length > 0) {
    if (values.summary) {
      console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${allMissing.length} imágenes de ítems faltantes.`));
    } else {
      console.log(styleText('red', '\n⚠️ DETALLE DE IMÁGENES FALTANTES:'));
      const limit = 30;
      const toPrint = allMissing.slice(0, limit);
      toPrint.forEach(i => {
        console.log(`   - 🚫 ${styleText('bold', i.name)} (ID: ${i.id})`);
        console.log(`        Tiendas:       ${i.shops.join(' y ') || 'Ninguna (Solo Base)'}`);
        i.expectedPaths.forEach(p => {
          const relPath = path.relative(process.cwd(), p);
          console.log(`        Ruta esperada: ${styleText('underline', relPath)}`);
        });
      });
      if (allMissing.length > limit) {
        console.log(styleText('cyan', `\n[INFO] Se muestran solo las primeras ${limit} de un total de ${allMissing.length} imágenes faltantes para evitar saturar la terminal.`));
        console.log(styleText('cyan', `👉 Para guardar el reporte completo a un archivo: npm run audit -- --output=scratch/item_assets_report.txt (o añade flags directamente al script)`));
      }
    }
  } else {
    console.log(styleText('green', '\n🎉 ¡Excelente! Todas las imágenes de ítems de ambas tiendas están presentes físicamente en el sistema.'));
  }

  if (values.output) {
    const outputPath = path.resolve(process.cwd(), values.output as string);
    const lines = [
      `--- ITEM IMAGE ASSETS AUDIT REPORT ---`,
      `Total Local Shop: ${localShopItems.length} (Missing: ${localMissing.length})`,
      `Total BC Shop: ${bcShopItems.length} (Missing: ${bcMissing.length})`,
      `\nDetailed Missing Items:`
    ];
    allMissing.forEach(i => {
      lines.push(`- [MISSING] ${i.name} (ID: ${i.id}) [Shops: ${i.shops.join(', ') || 'None'}]`);
      i.expectedPaths.forEach(p => lines.push(`  Expected: ${path.relative(process.cwd(), p)}`));
    });
    await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
    console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${values.output}`));
  }
}

main().catch(console.error);

/**
 * scripts/convert_assets.ts
 * 
 * ZERO-CONFIG ASSET PIPELINE (Node.js 26+) - MULTICORE OPTIMIZED
 * 
 * Escanea _raw-assets, convierte a WebP en paralelo y genera catálogos y bases de datos.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { isMainThread, parentPort, Worker } from 'node:worker_threads';
import sharp from 'sharp';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import { MAP_ROUTE_MAPPING } from '../../src/data/world/map-assets.ts';
import { TRAINER_TYPES } from '../../src/data/player/trainerTypes.ts';

// Speed up execution
enableCompileCache();

const SOURCE_DIR = path.resolve(process.cwd(), '_raw-assets');
const PUBLIC_ASSETS_DIR = path.resolve(process.cwd(), 'public', 'assets');

export interface AnimatedSpriteData {
  readonly frames: number;
  readonly size: number;
  readonly feetY: number;
  readonly feetX: number;
  readonly bodyH: number;
  readonly bodyW: number;
  readonly bodyRadius: number;
}

// Interfaces para comunicación de Workers
interface ProcessTask {
  type: 'processFile';
  filePath: string;
}

interface AnalyzeTask {
  type: 'analyzeAnimated';
  filePath: string;
}

type WorkerTask = ProcessTask | AnalyzeTask;

interface ProcessResult {
  type: 'processFile';
  filePath: string;
  success: boolean;
  environmentFile?: string;
  feetPoints?: { feetY: number; feetX: number };
  isMap?: boolean;
  destFiles: string[];
  error?: string;
}

interface AnalyzeResult {
  type: 'analyzeAnimated';
  filePath: string;
  success: boolean;
  spriteKey: string;
  animatedData?: AnimatedSpriteData;
  error?: string;
}

type WorkerResult = ProcessResult | AnalyzeResult;

// ============================================================================
// LÓGICA DEL WORKER (HILO SECUNDARIO)
// ============================================================================

if (!isMainThread) {
  parentPort?.on('message', async (task: WorkerTask) => {
    try {
      if (task.type === 'processFile') {
        const result = await handleProcessFile(task.filePath);
        parentPort?.postMessage({ type: 'processFile', filePath: task.filePath, ...result });
      } else if (task.type === 'analyzeAnimated') {
        const result = await handleAnalyzeAnimated(task.filePath);
        parentPort?.postMessage({ type: 'analyzeAnimated', filePath: task.filePath, ...result });
      }
    } catch (err: unknown) {
      parentPort?.postMessage({
        type: task.type,
        filePath: task.filePath,
        success: false,
        error: (err as Error).message,
        destFiles: []
      });
    }
  });
}

async function handleProcessFile(filePath: string) {
  const ext = path.extname(filePath).toLowerCase();
  if (!['.png', '.jpg', '.jpeg', '.webp'].includes(ext)) {
    return { success: false, destFiles: [], error: 'Unsupported extension' };
  }

  const relPath = path.relative(SOURCE_DIR, filePath);
  const destPath = path.join(process.cwd(), relPath);
  const destDir = path.dirname(destPath);
  const destFile = path.join(destDir, `${path.parse(destPath).name}.webp`);

  await fs.mkdir(destDir, { recursive: true });

  const isLossless = ['sprites', 'icons', 'badges', 'items', 'pixel'].some(p => 
    filePath.toLowerCase().includes(p)
  );

  let image = sharp(filePath);
  const metadata = await image.metadata();

  const webpOptions: sharp.WebpOptions = { effort: 6 };
  if (isLossless) {
    webpOptions.lossless = true;
  } else {
    const maxDim = Math.max(metadata.width || 0, metadata.height || 0);
    if (maxDim < 400) {
      webpOptions.quality = 100;
    } else if (maxDim < 1000) {
      webpOptions.quality = 95;
    } else {
      webpOptions.quality = 80;
    }
  }

  const pathSegments = relPath.split(path.sep);
  const isMap = pathSegments.includes('maps');
  const destFiles: string[] = [destFile];

  if (isMap) {
    image = image.resize({ width: 600, kernel: 'nearest' });
  }

  await image.webp(webpOptions).toFile(destFile);

  if (isMap) {
    const destMobileFile = path.join(destDir, `${path.parse(destPath).name}_mobile.webp`);
    await sharp(filePath)
      .resize({ width: 400, kernel: 'nearest' })
      .webp(webpOptions)
      .toFile(destMobileFile);
    destFiles.push(destMobileFile);
  }

  let environmentFile: string | undefined;
  if (destDir.includes('environment')) {
    environmentFile = path.parse(destPath).name;
  }

  const posixRelPath = relPath.split(path.sep).join(path.posix.sep);
  let feetPoints: { feetY: number; feetX: number } | undefined;

  const isSpriteWithFeet = (posixRelPath.toLowerCase().includes('sprites/pokemon') || 
                            posixRelPath.toLowerCase().includes('sprites/trainers') ||
                            posixRelPath.toLowerCase().includes('sprites/npc')) && 
                           !posixRelPath.toLowerCase().includes('sprites/pokemon/egg');

  if (isSpriteWithFeet) {
    feetPoints = await calculateFeetPointsWorker(filePath);
  }

  return {
    success: true,
    destFiles,
    environmentFile,
    feetPoints,
    isMap
  };
}

async function calculateFeetPointsWorker(filePath: string): Promise<{ feetY: number; feetX: number }> {
  try {
    const { data, info } = await sharp(filePath).raw().toBuffer({ resolveWithObject: true });
    const width = info.width;
    const height = info.height;
    const channels = info.channels;

    if (channels < 4) {
      return { feetY: 0.9, feetX: 0.5 };
    }

    const size = Math.min(width, height);
    let minX = size;
    let maxX = 0;
    let lowestY = -1;

    // Scan the first frame to find bounding box in X
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < size; x++) {
        const index = (y * width + x) * channels;
        const alpha = data[index + 3] ?? 0;
        if (alpha > 50) {
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
        }
      }
    }

    // Scan from bottom to top in the first frame to find the lowest non-empty pixel row (feetY)
    for (let y = height - 1; y >= 0; y--) {
      let rowHasOpaque = false;
      for (let x = 0; x < size; x++) {
        const index = (y * width + x) * channels;
        const alpha = data[index + 3] ?? 0;
        if (alpha > 50) {
          rowHasOpaque = true;
          break;
        }
      }
      if (rowHasOpaque) {
        lowestY = y;
        break;
      }
    }

    if (lowestY !== -1) {
      const centerX = (minX + maxX) / 2;
      return {
        feetY: Number((lowestY / height).toFixed(4)),
        feetX: Number((centerX / size).toFixed(4))
      };
    }
  } catch {
    // Silently fall back
  }
  return { feetY: 0.9, feetX: 0.5 };
}

async function handleAnalyzeAnimated(filePath: string) {
  try {
    const spriteKey = path.parse(filePath).name;
    const image = sharp(filePath);
    const metadata = await image.metadata();
    const width = metadata.width || 0;
    const height = metadata.height || 0;

    const frames = Math.round(width / height) || 1;
    const size = height;

    const firstFrameBuffer = await image
      .clone()
      .extract({ left: 0, top: 0, width: size, height: size })
      .raw()
      .toBuffer({ resolveWithObject: true });

    const data = firstFrameBuffer.data;
    const channels = firstFrameBuffer.info.channels;

    let minX = size;
    let maxX = 0;
    let minY = size;
    let maxY = 0;
    let lowestY = -1;
    let hasOpaque = false;

    for (let y = 0; y < size; y++) {
      for (let x = 0; x < size; x++) {
        const idx = (y * size + x) * channels;
        const alpha = channels >= 4 ? (data[idx + 3] ?? 0) : 255;
        if (alpha > 50) {
          hasOpaque = true;
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }

    if (hasOpaque) {
      // Scan from bottom to top to find the first non-empty pixel row (lowestY)
      for (let y = size - 1; y >= 0; y--) {
        let rowHasOpaque = false;
        for (let x = 0; x < size; x++) {
          const idx = (y * size + x) * channels;
          const alpha = channels >= 4 ? (data[idx + 3] ?? 0) : 255;
          if (alpha > 50) {
            rowHasOpaque = true;
            break;
          }
        }
        if (rowHasOpaque) {
          lowestY = y;
          break;
        }
      }
    }

    let feetY = 0.9;
    let feetX = 0.5;
    let bodyH = 0.8;
    let bodyW = 0.8;

    if (hasOpaque && lowestY !== -1) {
      const centerX = (minX + maxX) / 2;
      feetY = Number((lowestY / size).toFixed(4));
      feetX = Number((centerX / size).toFixed(4));
      bodyH = Number(((maxY - minY + 1) / size).toFixed(4));
      bodyW = Number(((maxX - minX + 1) / size).toFixed(4));
    }

    const bodyRadius = Number((bodyH / 2).toFixed(4));

    return {
      success: true,
      spriteKey,
      animatedData: {
        frames,
        size,
        feetY,
        feetX,
        bodyH,
        bodyW,
        bodyRadius
      }
    };
  } catch (err: unknown) {
    return { success: false, spriteKey: path.parse(filePath).name, error: (err as Error).message };
  }
}

// ============================================================================
// LÓGICA DEL HILO PRINCIPAL
// ============================================================================

async function getFilesToConvert(dir: string): Promise<string[]> {
  const files: string[] = [];
  const pattern = '**/*.{png,jpg,jpeg,webp}';

  for await (const entry of fs.glob(pattern, { cwd: dir })) {
    files.push(path.resolve(dir, entry));
  }
  return files;
}

// Orquestador de Tareas en Pool de Workers
function runTasksInParallel(tasks: WorkerTask[], maxWorkers: number): Promise<WorkerResult[]> {
  return new Promise((resolve) => {
    const results: WorkerResult[] = [];
    let activeWorkers = 0;
    let taskIndex = 0;
    const workers: Worker[] = [];

    if (tasks.length === 0) {
      resolve([]);
      return;
    }

    const startWorker = () => {
      const worker = new Worker(import.meta.filename, {
        execArgv: [...process.execArgv, '--no-warnings']
      });
      workers.push(worker);

      const sendNextTask = () => {
        if (taskIndex >= tasks.length) {
          worker.terminate();
          activeWorkers--;
          if (activeWorkers === 0) {
            resolve(results);
          }
          return;
        }

        const currentTask = tasks[taskIndex++];
        worker.postMessage(currentTask);
      };

      worker.on('message', (result: WorkerResult) => {
        results.push(result);
        sendNextTask();
      });

      worker.on('error', (err) => {
        console.error(`Worker error:`, err);
        sendNextTask();
      });

      activeWorkers++;
      sendNextTask();
    };

    const numWorkers = Math.min(maxWorkers, tasks.length);
    for (let i = 0; i < numWorkers; i++) {
      startWorker();
    }
  });
}

async function main() {
  console.log(styleText('bold', '\n--- 🖼️  ASSET PIPELINE (MULTICORE) ---'));

  try {
    await fs.access(SOURCE_DIR);
  } catch {
    console.error(styleText('red', `Error: Directorio fuente '${SOURCE_DIR}' no encontrado.`));
    process.exit(1);
  }

  // Limpieza determinista: borrar public/assets antes de reconstruir (no fatal si está bloqueado)
  console.log(styleText('yellow', `   🧹 Limpiando ${path.relative(process.cwd(), PUBLIC_ASSETS_DIR)}...`));
  try {
    await fs.rm(PUBLIC_ASSETS_DIR, { recursive: true, force: true });
  } catch (err) {
    console.log(styleText('yellow', `   ⚠️ Warning: No se pudo limpiar public/assets por completo (${(err as Error).message}). Se continuará con la sobreescritura de archivos.`));
  }
  await fs.mkdir(PUBLIC_ASSETS_DIR, { recursive: true });

  const files = await getFilesToConvert(SOURCE_DIR);
  console.log(styleText('yellow', `   Encontrados ${files.length} archivos en _raw-assets.\n`));

  const maxWorkers = Math.max(1, os.availableParallelism());
  console.log(styleText('blue', `   Iniciando pool con ${maxWorkers} workers en paralelo...`));

  const processTasks: WorkerTask[] = files.map(file => ({ type: 'processFile', filePath: file }));
  const processResults = await runTasksInParallel(processTasks, maxWorkers) as ProcessResult[];

  const environmentFiles: string[] = [];
  const pokemonFeetDatabase: Record<string, { feetY: number; feetX: number }> = {};

  for (const res of processResults) {
    if (!res.success) {
      console.error(styleText('red', `   [ERROR] No se pudo procesar ${res.filePath}: ${res.error}`));
      continue;
    }

    for (const dest of res.destFiles) {
      console.log(styleText('green', `   [OK] ${path.relative(process.cwd(), dest)}`));
    }

    if (res.environmentFile) {
      environmentFiles.push(res.environmentFile);
    }

    if (res.feetPoints) {
      const relPath = path.relative(SOURCE_DIR, res.filePath);
      const posixRelPath = relPath.split(path.sep).join(path.posix.sep);
      const normalizedPath = '/' + posixRelPath.replace(/^public\//, '').replace(/\.(png|jpg|jpeg|webp)$/i, '.webp');
      pokemonFeetDatabase[normalizedPath] = res.feetPoints;
    }
  }

  // Ordenar y autogenerar el catálogo de ex-arbustos en TypeScript
  console.log(styleText('yellow', `\n   📦 Generando catálogo de coberturas ambientales en src/logic/environment/bushCatalog.ts...`));

  const repeatedPrefixes = new Set<string>();
  const prefixCounts = new Map<string, number>();
  const filePrefixes = new Map<string, string>();

  for (const filename of environmentFiles) {
    const match = filename.match(/^([a-zA-Z]+)-(\d+)$/);
    if (match && match[1]) {
      const prefix = match[1];
      filePrefixes.set(filename, prefix);
      prefixCounts.set(prefix, (prefixCounts.get(prefix) || 0) + 1);
    }
  }

  for (const [prefix, count] of prefixCounts.entries()) {
    if (count >= 1) {
      repeatedPrefixes.add(prefix);
    }
  }

  const dynamicCatalog: Record<string, string[]> = {};

  for (const prefix of repeatedPrefixes) {
    dynamicCatalog[prefix] = [];
  }

  for (const filename of environmentFiles) {
    const prefix = filePrefixes.get(filename);
    if (prefix && repeatedPrefixes.has(prefix)) {
      const catalogArr = dynamicCatalog[prefix];
      if (catalogArr) {
        catalogArr.push(filename);
      }
    }
  }

