      ...frontFiles.map(file => ({
        type: 'analyzeAnimated' as const,
        filePath: path.join(ANIMATED_FRONT_DIR, file)
      })),
      ...backFiles.map(file => ({
        type: 'analyzeAnimated' as const,
        filePath: path.join(ANIMATED_BACK_DIR, file)
      }))
    ];

