  }
}
console.log(`✅ Diccionario listo. ${idMap.size} usuarios registrados.`);

// Función de reemplazo recursivo de IDs
function replaceUserIds(value: unknown, mapping: Map<string, string>): unknown {
  if (typeof value === 'string') {
    return mapping.get(value) || value;
  }
  if (Array.isArray(value)) {
    return value.map(item => replaceUserIds(item, mapping));
  }
  if (value !== null && typeof value === 'object') {
    const newObj: Record<string, unknown> = {};
    for (const key of Object.keys(value)) {
      newObj[key] = replaceUserIds((value as Record<string, unknown>)[key], mapping);
    }
    return newObj;
  }
  return value;
}

// Función de transformación de fila
function transformRow(
  row: Record<string, unknown>,
  tableName: string,
  mapping: Map<string, string>,
  validCols: Set<string>,
  hasIntPkId: boolean
): Record<string, unknown> {
  const newRow: Record<string, unknown> = {};

  // Clonar para evitar mutar el objeto del backup original
  const rowCopy = { ...row };

  // Pre-mapeos específicos de nombres de columna
  if (tableName === 'game_saves' && 'id' in rowCopy) {
    rowCopy['last_save_id'] = rowCopy['id'];
  }
  if (tableName === 'battle_invites' && 'challenger_id' in rowCopy) {
    rowCopy['sender_id'] = rowCopy['challenger_id'];
  }

  for (const col of Object.keys(rowCopy)) {
    // Filtrar columnas inexistentes en SQLite local
    if (!validCols.has(col)) {
      continue;
    }

    let val = rowCopy[col];

    // Omitir el campo 'id' si el SQLite local lo maneja como INTEGER PRIMARY KEY AUTOINCREMENT
    if (col === 'id' && hasIntPkId && typeof val === 'string') {
      continue;
    }

    // No alterar los correos electrónicos reales
    if (col === 'email' || col === 'winner_email' || col === 'player_email') {
      newRow[col] = val;
      continue;
    }

    // Transformar datos de guardado (JSON)
    if (tableName === 'game_saves' && col === 'save_data') {
      try {
        const parsed = typeof val === 'string' ? JSON.parse(val) : val;

        // Migrate inventory keys to IDs if present
        if (parsed && parsed.inventory && typeof parsed.inventory === 'object') {
          // Resolve standard names using resolved normalized strings (matching test_migration_unit mapping)
          const resolveNormalizedName = (name: string): string => {
            const norm = name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]/g, '');
            const aliases: Record<string, string> = {
              'potion': 'Poción',
              'pocion': 'Poción',
              'pocian': 'Poción',
              'pociaon': 'Poción',
              'superpotion': 'Súper Poción',
              'superpocion': 'Súper Poción',
              'hyperpotion': 'Hiper Poción',
              'hiperpocion': 'Hiper Poción',
              'maxpotion': 'Poción Máxima',
              'pocionmaxima': 'Poción Máxima',
              'firestone': 'Piedra Fuego',
              'waterstone': 'Piedra Agua',
              'thunderstone': 'Piedra Trueno',
              'leafstone': 'Piedra Hoja',
              'moonstone': 'Piedra Lunar',
              'sunstone': 'Piedra Solar',
              'vigorcandy': 'Caramelo de vigor',
              'repel': 'Repelente',
              'iman': 'Imán',
              'elixir': 'Elixir',
              'subidapp': 'Subida de PP',
              'subidadepp': 'Subida de PP',
              'mttoxico': 'MT06 Tóxico',
              'ocasoball': 'Ocaso Ball',
              'turnoball': 'Turno Ball',
              'ultraball': 'Ultra Ball',
              'masterball': 'Master Ball',
              'superball': 'Súper Ball',
              'pokeball': 'Pokéball',
              'pokaball': 'Pokéball',
              'brazalrecio': 'Brazal Recio',
              'brazalrecia': 'Brazal Recio',
              'cintorecio': 'Cinto Recio',
              'cintorecia': 'Cinto Recio',
              'pesarecia': 'Pesa Recia',
              'bandarecia': 'Banda Recia',
              'lenterecia': 'Lente Recia',
              'franjarecia': 'Franja Recia',
              'bayadeoro': 'Baya de Oro',
              'bayaoro': 'Baya de Oro',
              'piedraeterna': 'Piedra Eterna',
              'lazodestino': 'Lazo Destino',
              'caramelovigor': 'Caramelo de vigor',
              'fishingrod': 'Caña de pescar',
              'fishingrodgood': 'Caña Buena',
              'fishingrodsuper': 'Supercaña',
              'pickaxe': 'Pico de excavación',
              'pickaxesilver': 'Pico Bueno',
              'pickaxegold': 'Superpico',
              'brush': 'Pincel de excavación',
              'brushgood': 'Pincel Buena',
              'brushsuper': 'Superpincel',
              'carbon': 'Carbón vegetal',
              'carbonvegetal': 'Carbón vegetal'
            };
            return aliases[norm] || name;
          };

          const itemMapping: Record<string, string> = {};
          for (const item of SHOP_ITEMS) {
            itemMapping[item.name] = item.id;
          }
          const validIds = new Set<string>(SHOP_ITEMS.map(i => i.id));
          validIds.add('bicycle');

          const newInv: Record<string, number> = {};
          for (const [key, qty] of Object.entries(parsed.inventory)) {
            const resolvedName = resolveNormalizedName(key);
            let mappedId = itemMapping[resolvedName];
            if (!mappedId) {
              if (validIds.has(key)) {
                mappedId = key;
              } else {
                throw new Error(`Item no reconocido en save local: "${key}"`);
              }
            }
            newInv[mappedId] = qty as number;
          }
          parsed.inventory = newInv;
        }

        const transformed = replaceUserIds(parsed, mapping);
        val = JSON.stringify(transformed);
      } catch {
        val = replaceUserIds(val, mapping);
      }
    } else if (tableName === 'profiles' && col === 'db_version') {
      val = 3;
    } else if (tableName === 'market_listings' && col === 'data') {
      try {
        const parsed = typeof val === 'string' ? JSON.parse(val) : val;
        const transformed = replaceUserIds(parsed, mapping);
        val = JSON.stringify(transformed);
      } catch {
        val = replaceUserIds(val, mapping);
      }
    } else {
      val = replaceUserIds(val, mapping);
    }

    // Convertir booleanos a 0/1 para SQLite
    if (typeof val === 'boolean') {
      val = val ? 1 : 0;
    } else if (val !== null && typeof val === 'object') {
      val = JSON.stringify(val);
    }

    newRow[col] = val;
  }
  return newRow;
}

// 4. Inicializar Base de Datos SQLite temporal
const tempDir = path.resolve('database/temp');
if (!fs.existsSync(tempDir)) {
  fs.mkdirSync(tempDir, { recursive: true });
}

const dbPath = path.join(tempDir, 'imported.db');
if (fs.existsSync(dbPath)) {
  fs.unlinkSync(dbPath);
}

console.log(`🔌 Creando base de datos SQLite temporal en: ${dbPath}`);
using db = new DatabaseSync(dbPath);

// 5. Crear esquemas de tablas
console.log('⚡ Inicializando esquemas de tablas...');
db.exec('PRAGMA foreign_keys = OFF;');
TABLES_SCHEMA.forEach(schema => {
  try {
    db.exec(`CREATE TABLE IF NOT EXISTS ${schema};`);
  } catch (e) {
    console.error(`⚠️ Error al crear tabla con esquema: ${schema.split(' ')[0]} - ${(e as Error).message}`);
  }
});

// Extraer metadatos de las columnas válidas de SQLite local
const tableColumns = new Map<string, Set<string>>();
const tableIntPk = new Map<string, boolean>();

TABLES_SCHEMA.forEach(schemaStr => {
  const parts = schemaStr.split('(');
  if (parts.length < 2) return;
  const tableName = parts[0]!.replace('CREATE TABLE IF NOT EXISTS', '').trim();

  const info = db.prepare(`PRAGMA table_info(${tableName});`).all() as Array<{ name: string; type: string; pk: number }>;
  if (info.length === 0) return;

  const colSet = new Set<string>();
  let hasIntPkId = false;

  for (const col of info) {
    const colName = col.name;
    const colType = col.type;
    const isPk = col.pk;

    colSet.add(colName);
    if (colName === 'id' && colType.toUpperCase() === 'INTEGER' && isPk === 1) {
      hasIntPkId = true;
    }
  }

  tableColumns.set(tableName, colSet);
  tableIntPk.set(tableName, hasIntPkId);
});

// 6. Inserción de Datos Transformados
console.log('⚙️ Insertando y transformando datos...');
for (const tableName of Object.keys(backupData.data)) {
  const rows = backupData.data[tableName];
  if (!rows || rows.length === 0) continue;

  const validCols = tableColumns.get(tableName);
  const hasIntPkId = tableIntPk.get(tableName) || false;

  if (!validCols) {
    console.log(`⚠️ Saltando tabla "${tableName}" (no definida en el esquema de la base de datos local)`);
    continue;
  }

  // Mapear y filtrar cada fila
  const transformedRows = rows
    .map(r => transformRow(r as Record<string, unknown>, tableName, idMap, validCols, hasIntPkId))
    .filter(row => Object.keys(row).length > 0);

  if (transformedRows.length === 0) continue;

  // Tomamos las columnas presentes en el primer registro transformado
  const columns = Object.keys(transformedRows[0]!);
  const placeholders = columns.map(() => '?').join(', ');
  const sql = `INSERT INTO ${tableName} (${columns.join(', ')}) VALUES (${placeholders});`;

  try {
    const stmt = db.prepare(sql);
    db.exec('BEGIN TRANSACTION;');
    for (const row of transformedRows) {
      const values = columns.map(col => {
        const val = row[col];
        if (val === null || val === undefined) return null;
        if (typeof val === 'string' || typeof val === 'number' || typeof val === 'bigint') return val;
        if (val instanceof Uint8Array) return val;
        return String(val);
      }) as (string | number | bigint | Uint8Array | null)[];
      stmt.run(...values);
    }
    db.exec('COMMIT;');
    console.log(`✅ Tabla [${tableName}] importada con éxito: ${transformedRows.length} registros.`);
  } catch (err) {
    try {
      db.exec('ROLLBACK;');
    } catch {
      // Ignorar si no había transacción activa
    }
    console.error(`❌ Error al importar la tabla [${tableName}]: ${(err as Error).message}`);
  }
}

db.exec('PRAGMA foreign_keys = ON;');
db.close();

console.log('\n==================================================');
console.log('🎉 PROCESO DE IMPORTACIÓN A SQLITE COMPLETADO CON ÉXITO');
console.log(`📂 Archivo listo para el navegador en: database/temp/imported.db`);
console.log('==================================================\n');

/**
 * @file restore_supabase_db.ts
 * @description Script automático para restaurar un respaldo completo (backup) en formato JSON
 * hacia la base de datos Supabase elegida (nube o NAS), extrayendo credenciales y Tenant ID del .env maestro.
 * 
 * UTILIDAD:
 * Permite al usuario elegir un servidor (--server=<perfil>) y un archivo de respaldo opcional (--file=<ruta>).
 * Si no se especifica --file, detecta automáticamente el respaldo más reciente para ese servidor en database/backups/.
 * Realiza una limpieza limpia en orden inverso y restaura transaccionalmente todas las filas.
 * 
 * CUMPLE CON:
 * - Regla de Aislamiento y Parseo Multi-Servidor (env-multi-server-parser).
 * - Estándares Node.js 26+ (Explicit Resource Management con 'using', prefijos node:).
 * - Arquitectura Zero-Warning y Zero-Any.
 */

import fsPromises from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import postgres from 'postgres';
import { readAndParseEnv, buildDatabaseUrl } from '../lib/supabaseClient.ts';

// Optimizar ejecución en ejecuciones sucesivas
enableCompileCache();

const BACKUPS_DIR = path.resolve(process.cwd(), 'database/backups');

export async function restoreSupabaseDb() {
  console.log(styleText('bold', '\n--- 🔄 SUPABASE DATABASE RESTORE MANAGER (Node.js 26+) ---'));

  const serverConfigs = await readAndParseEnv();
  const baseProfiles = Object.keys(serverConfigs);
  if (baseProfiles.length === 0) {
    console.error(styleText('red', '❌ Error: No se encontraron configuraciones de servidor (SERVER_<profile>_*) en el .env.'));
    process.exit(1);
  }

  const allAvailable = Array.from(new Set(baseProfiles.concat(Object.values(serverConfigs).map(c => c.ID).filter(Boolean) as string[])));

  // Parsear argumentos de la línea de comandos
  const args = process.argv.slice(2);
  let serverArg: string | undefined;
  const serverFlagIdx = args.findIndex(a => a === '--server');
  if (serverFlagIdx !== -1 && args[serverFlagIdx + 1] !== undefined) {
    serverArg = args[serverFlagIdx + 1];
  } else {
    serverArg = args.find(a => a.startsWith('--server='))?.split('=')[1];
  }

  let fileArg: string | undefined;
  const fileFlagIdx = args.findIndex(a => a === '--file');
  if (fileFlagIdx !== -1 && args[fileFlagIdx + 1] !== undefined) {
    fileArg = args[fileFlagIdx + 1];
  } else {
    fileArg = args.find(a => a.startsWith('--file='))?.split('=')[1];
  }

  if (!serverArg) {
    console.log(styleText('yellow', '⚠️  Especifica qué servidor deseas restaurar usando la bandera --server=<perfil>.'));
    console.log(styleText('cyan', `Perfiles disponibles: ${allAvailable.join(', ')}`));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:restore -- --server=nas_franco'));
    console.log(styleText('gray', 'Ejemplo con archivo específico: npm run servers:db:restore -- --server=nas_franco --file=database/backups/nas_franco_backup_...json'));
    process.exit(1);
  }

  const profile = serverArg;
  let conf = serverConfigs[profile];
  if (!conf) {
    const found = Object.keys(serverConfigs).find(p => serverConfigs[p]?.ID === profile);
    if (found) conf = serverConfigs[found];
  }
  if (!conf) {
    console.error(styleText('red', `❌ Error: El perfil o ID "${profile}" no existe en el archivo .env.`));
    process.exit(1);
  }

  const canonicalName = conf.ID || profile;

  console.log(styleText('bold', styleText('blue', `\n==================================================`)));
  console.log(styleText('bold', styleText('cyan', `🔄 INICIANDO RESTAURACIÓN DE BASE DE DATOS: [${canonicalName}]`)));
  console.log(styleText('bold', styleText('blue', `==================================================`)));

  // 1. Resolver archivo de respaldo a utilizar
  let targetBackupPath = fileArg ? path.resolve(process.cwd(), fileArg) : '';

  if (!targetBackupPath) {
    const serverBackupDir = path.join(BACKUPS_DIR, canonicalName);
    console.log(styleText('cyan', `🔍 Buscando archivo de respaldo más reciente para [${canonicalName}] en database/backups/${canonicalName}/...`));
    try {
      const files = await fsPromises.readdir(serverBackupDir);
      const matchingFiles = files
        .filter(f => f.startsWith(`${canonicalName}_backup_`) && f.endsWith('.json'))
        .sort()
        .reverse();

      if (matchingFiles.length === 0 || matchingFiles[0] === undefined) {
        console.error(styleText('red', `❌ Error: No se encontraron archivos de respaldo automáticos para "${canonicalName}" en ${serverBackupDir}.`));
        console.error(styleText('yellow', `👉 Ejecuta primero un respaldo con: npm run servers:db:backup -- --server=${canonicalName} o especifica --file=<ruta>`));
        process.exit(1);
      }

      targetBackupPath = path.join(serverBackupDir, matchingFiles[0]);
      console.log(styleText('green', `🏷️  Archivo de respaldo detectado automáticamente: ${matchingFiles[0]}`));
    } catch (rErr: unknown) {
      console.error(styleText('red', `❌ Error al inspeccionar el directorio de respaldos: ${(rErr as Error).message}`));
      process.exit(1);
    }
  } else {
    console.log(styleText('green', `🏷️  Archivo de respaldo especificado manualmente: ${fileArg}`));
  }

  // 2. Leer y validar archivo de respaldo
  let backupContent = '';
  try {
    await using backupHandle = await fsPromises.open(targetBackupPath, 'r');
    backupContent = await backupHandle.readFile({ encoding: 'utf-8' });
  } catch (bErr: unknown) {
    console.error(styleText('red', `❌ Error al leer el archivo de respaldo ${targetBackupPath}: ${(bErr as Error).message}`));
    process.exit(1);
  }

  interface BackupObject {
    metadata?: { profile?: string; timestamp?: string; totalTables?: number; totalRows?: number };
    data?: Record<string, Record<string, unknown>[]>;
    auth?: {
      users?: Record<string, unknown>[];
      identities?: Record<string, unknown>[];
    };
  }

  let backupObj: BackupObject;
  try {
    backupObj = JSON.parse(backupContent) as BackupObject;
    if (!backupObj.data || typeof backupObj.data !== 'object') {
      throw new Error('El archivo JSON no tiene la propiedad "data" estructurada.');
    }
  } catch (jErr: unknown) {
    console.error(styleText('red', `❌ Error: Archivo de respaldo JSON inválido o corrupto: ${(jErr as Error).message}`));
    process.exit(1);
  }

  const backupData = backupObj.data;
  const tableNames = Object.keys(backupData);
  console.log(styleText('cyan', `📦 Respaldo cargado en memoria: ${tableNames.length} tablas detectadas (Fecha de origen: ${backupObj.metadata?.timestamp || 'Desconocida'}).`));

  // 3. Construir URL de Conexión Postgres
  const dbUrl = buildDatabaseUrl(conf, canonicalName);

  if (!dbUrl) {
    console.error(styleText('red', `❌ Error: No se pudo construir la URL de conexión Postgres para el perfil "${canonicalName}".`));
    console.error(styleText('yellow', `👉 Asegúrate de tener SERVER_${profile}_POSTGRES_PASSWORD y SERVER_${profile}_SUPABASE_PUBLIC_URL en el .env`));
    process.exit(1);
  }

  if (dbUrl.includes('placeholder')) {
    console.error(styleText('red', `❌ Error: La contraseña para "${canonicalName}" es un placeholder. No se puede restaurar.`));
    process.exit(1);
  }

  const isSupabaseCloud = dbUrl.includes('.supabase.co');
  console.log(styleText('cyan', `🔌 Conectando al servidor Postgres de [${canonicalName}]...`));

  const sql = postgres(dbUrl, { ssl: isSupabaseCloud ? 'require' : false, max: 1 });

  try {
    // 3.5. Obtener lista de tablas existentes en el destino
    interface TableRow { table_name: string }
    interface LegacyPassiveBattleResult {
      id: string;
      attacker_id: string;
      defender_id: string;
      result: string;
      attacker_elo_change?: number;
      defender_elo_change?: number;
      created_at: string;
    }

    const tables = await sql<TableRow[]>`
      SELECT table_name 
      FROM information_schema.tables 
      WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
    `;
    const existingTables = new Set(tables.map(t => t.table_name));

    interface ColumnRow { table_name: string; column_name: string }
    const cols = await sql<ColumnRow[]>`
      SELECT table_name, column_name 
      FROM information_schema.columns 
      WHERE table_schema = 'public'
    `;
    const tableColumns = new Map<string, Set<string>>();
    for (const col of cols) {
      if (!tableColumns.has(col.table_name)) {
        tableColumns.set(col.table_name, new Set());
      }
      tableColumns.get(col.table_name)?.add(col.column_name);
    }

    interface AuthColumnRow { table_name: string; column_name: string; is_generated?: string; is_updatable?: string }
    const authCols = await sql<AuthColumnRow[]>`
      SELECT table_name, column_name, is_generated, is_updatable
      FROM information_schema.columns 
      WHERE table_schema = 'auth'
    `;
    const authTableColumns = new Map<string, Set<string>>();
    for (const col of authCols) {
      if (col.is_generated === 'ALWAYS') continue;
      if (col.is_updatable === 'NO') continue;
      if (col.table_name === 'identities' && col.column_name === 'email') continue;
      if (!authTableColumns.has(col.table_name)) {
        authTableColumns.set(col.table_name, new Set());
      }
      authTableColumns.get(col.table_name)?.add(col.column_name);
    }

    // Recolectar todos los user_ids del respaldo para asegurar su existencia en auth.users
    const backupUserIds = new Map<string, string>();
    const profileRows = backupData['profiles'] || [];
    for (const r of profileRows) {
      const userId = String(r.id || r.user_id || '');
      const email = String(r.email || `user_${userId}@test.com`);
      if (userId && userId.length === 36) {
        backupUserIds.set(userId, email);
      }
    }

    const userIdKeys = ['user_id', 'requester_id', 'addressee_id', 'sender_id', 'opponent_id', 'player_id', 'winner_id'];
    for (const tableName of tableNames) {
      const rows = backupData[tableName];
      if (!rows) continue;
      for (const r of rows) {
        for (const key of userIdKeys) {
          const val = String(r[key] || '');
          if (val && val.length === 36 && !backupUserIds.has(val)) {
            backupUserIds.set(val, `user_${val}@test.com`);
          }
        }
      }
    }

    // 4. Ordenar tablas por prioridad de dependencias (Padres primero para INSERT, Hijos primero para DELETE)
    const priorityOrder = ['system_config', '_migrations', 'events_config', 'profiles'];
    const orderedTables = [...tableNames].sort((a, b) => {
      const idxA = priorityOrder.indexOf(a);
      const idxB = priorityOrder.indexOf(b);
      if (idxA !== -1 && idxB !== -1) return idxA - idxB;
      if (idxA !== -1) return -1;
      if (idxB !== -1) return 1;
      return a.localeCompare(b);
    });

    console.log(styleText('yellow', `⚠️  Iniciando transacción de restauración. Se limpiarán las tablas existentes y se reinsertarán los datos del respaldo.`));

    await sql.begin(async (tx) => {
      // Paso A: Limpiar tablas públicas en orden inverso de dependencias (Hijos primero)
      const reverseOrderedTables = [...orderedTables].reverse();
      for (const tableName of reverseOrderedTables) {
        if (!existingTables.has(tableName)) {
          if (tableName === 'passive_battle_results' && existingTables.has('passive_battle_reports')) {
            try {
              await tx.unsafe(`DELETE FROM public.passive_battle_reports`);
              console.log(styleText('gray', `   🧹 Tabla passive_battle_reports (mapeada de passive_battle_results) limpiada correctamente.`));
            } catch (dErr: unknown) {
              console.error(styleText('yellow', `   ⚠️ Advertencia al limpiar tabla passive_battle_reports: ${(dErr as Error).message}`));
            }
          } else {
            console.log(styleText('yellow', `   ⚠️ Advertencia: La tabla "${tableName}" del respaldo no existe en el destino. Se omitirá la limpieza.`));
          }
          continue;
        }

        try {
          await tx.unsafe(`DELETE FROM public."${tableName}"`);
          console.log(styleText('gray', `   🧹 Tabla ${tableName} limpiada correctamente.`));
        } catch (dErr: unknown) {
          console.error(styleText('yellow', `   ⚠️ Advertencia al limpiar tabla ${tableName} (puede no existir o estar vacía): ${(dErr as Error).message}`));
        }
      }

      // Paso A.2: Limpiar tablas de auth si existe respaldo de auth para evitar conflictos
      const authBackup = backupObj.auth;
      const hasAuthBackup = authBackup && Array.isArray(authBackup.users) && authBackup.users.length > 0;
      if (hasAuthBackup) {
        try {
          console.log(styleText('cyan', `\n🧹 Limpiando tablas de autenticación en destino...`));
          await tx`DELETE FROM auth.identities`;
          console.log(styleText('gray', `   🧹 Tabla auth.identities limpiada correctamente.`));
          await tx`DELETE FROM auth.users`;
          console.log(styleText('gray', `   🧹 Tabla auth.users limpiada correctamente.`));
        } catch (cleanAuthErr: unknown) {
          console.error(styleText('yellow', `   ⚠️ Advertencia al limpiar tablas de auth: ${(cleanAuthErr as Error).message}`));
        }
      }

      // Paso A.5: Asegurar la existencia de todos los usuarios en auth.users y auth.identities
      if (hasAuthBackup && authBackup && Array.isArray(authBackup.users)) {
        console.log(styleText('cyan', `\n👤 Restaurando ${authBackup.users.length} usuarios auténticos en auth.users...`));
        const usersCols = authTableColumns.get('users');
        const emptyStringCols = new Set([
          'confirmation_token',
          'recovery_token',
          'email_change_token_new',
          'email_change',
          'email_change_token_current',
          'phone_change',
          'phone_change_token',
          'reauthentication_token'
        ]);

        if (usersCols) {
          for (const u of authBackup.users) {
            try {
              const cleanUser: Record<string, unknown> = {};
              for (const col of usersCols) {
                const val = u[col];
                if ((col === 'raw_app_meta_data' || col === 'raw_user_meta_data') && val !== null && val !== undefined) {
                  try {
                    cleanUser[col] = typeof val === 'string' ? JSON.parse(val) : val;
                  } catch {
                    cleanUser[col] = val;
                  }
                } else if (emptyStringCols.has(col)) {
                  cleanUser[col] = (val === null || val === undefined) ? '' : val;
                } else {
                  cleanUser[col] = val !== undefined ? val : null;
                }
              }
              const updateCols = Object.keys(cleanUser).filter(k => k !== 'id');
              await tx`
                INSERT INTO auth.users ${ tx(cleanUser) }
                ON CONFLICT (id) DO UPDATE SET ${ tx(cleanUser, ...updateCols) }
              `;
            } catch (authErr: unknown) {
              console.error(styleText('yellow', `   ⚠️ Advertencia al restaurar usuario ${u.id} (${u.email}): ${(authErr as Error).message}`));
            }
          }
        } else {
          console.error(styleText('red', '❌ Error: No se pudo obtener la definición de columnas para auth.users.'));
        }
      } else {
        console.log(styleText('cyan', `\n👤 Asegurando que todos los usuarios del respaldo (${backupUserIds.size}) existan en auth.users...`));
        for (const [userId, email] of backupUserIds.entries()) {
          try {
            await tx`
              INSERT INTO auth.users (id, email, aud, role, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous)
              VALUES (${userId}, ${email}, 'authenticated', 'authenticated', NOW(), '{}'::jsonb, '{}'::jsonb, false, false)
              ON CONFLICT (id) DO NOTHING
            `;
          } catch (authErr: unknown) {
            console.error(styleText('yellow', `   ⚠️ Advertencia al asegurar usuario ${userId} (${email}): ${(authErr as Error).message}`));
          }
        }
      }

      // Restaurar identidades si existen en el backup
      if (hasAuthBackup && authBackup && Array.isArray(authBackup.identities)) {
        console.log(styleText('cyan', `👤 Restaurando ${authBackup.identities.length} identidades de usuario en auth.identities...`));
        const idenCols = authTableColumns.get('identities');
        if (idenCols) {
          for (const iden of authBackup.identities) {
            try {
              const cleanIden: Record<string, unknown> = {};
              for (const col of idenCols) {
                const val = iden[col];
                if (col === 'identity_data' && val !== null && val !== undefined) {
                  try {
                    cleanIden[col] = typeof val === 'string' ? JSON.parse(val) : val;
                  } catch {
                    cleanIden[col] = val;
                  }
                } else {
                  cleanIden[col] = val !== undefined ? val : null;
                }
              }
              const updateCols = Object.keys(cleanIden).filter(k => k !== 'id');
              await tx`
                INSERT INTO auth.identities ${ tx(cleanIden) }
                ON CONFLICT (id) DO UPDATE SET ${ tx(cleanIden, ...updateCols) }
              `;
            } catch (idenErr: unknown) {
              console.error(styleText('yellow', `   ⚠️ Advertencia al restaurar identidad ${iden.id}: ${(idenErr as Error).message}`));
            }
          }
        } else {
          console.error(styleText('red', '❌ Error: No se pudo obtener la definición de columnas para auth.identities.'));
        }
      }

      console.log(styleText('green', `\n✨ Limpieza completada. Iniciando inserción de datos en orden jerárquico...`));

      // Paso B: Insertar filas en orden directo jerárquico (Padres primero)
      let totalRestoredRows = 0;
      for (const tableName of orderedTables) {
        let rows = backupData[tableName];
        if (!rows || rows.length === 0) {
          console.log(styleText('gray', `   ⏩ ${tableName}: 0 filas en el respaldo. Omitiendo.`));
          continue;
        }

        if (!existingTables.has(tableName)) {
          if (tableName === 'passive_battle_results' && existingTables.has('passive_battle_reports')) {
            console.log(styleText('cyan', `   🔄 Mapeando passive_battle_results a passive_battle_reports (${rows.length} filas)...`));
            const mappedRows = (rows as unknown as LegacyPassiveBattleResult[]).map((r) => ({
              id: r.id,
              user_id: r.attacker_id,
              opponent_id: r.defender_id,
              result: r.result,
              report_data: {
                attacker_elo_change: r.attacker_elo_change ?? 0,
                defender_elo_change: r.defender_elo_change ?? 0
              },
              created_at: r.created_at
            }));

            // Podar columnas inválidas para passive_battle_reports
            const validCols = tableColumns.get('passive_battle_reports');
            if (validCols) {
              for (const r of mappedRows) {
                for (const key of Object.keys(r)) {
                  if (!validCols.has(key)) {
                    delete (r as Record<string, unknown>)[key];
                  }
                }
              }
            }

            try {
              await tx`INSERT INTO public.passive_battle_reports ${tx(mappedRows)}`;
              totalRestoredRows += mappedRows.length;
              console.log(styleText('green', `   ✔️ passive_battle_reports (mapeada de passive_battle_results): ${mappedRows.length} filas restauradas exitosamente.`));
            } catch (iErr: unknown) {
              throw new Error(`Error al insertar en tabla adaptada "passive_battle_reports": ${(iErr as Error).message}`);
            }
          } else {
            console.log(styleText('yellow', `   ⏩ Tabla "${tableName}" no existe en el destino y no tiene mapeo. Omitiendo inserción.`));
          }
          continue;
        }

        // Podar columnas inválidas del respaldo que no existen en el destino
        const validCols = tableColumns.get(tableName);
        if (validCols) {
          rows = rows.map((r: Record<string, unknown>) => {
            const cleanRow: Record<string, unknown> = {};
            for (const key of Object.keys(r)) {
              if (validCols.has(key)) {
                cleanRow[key] = r[key];
              }
            }
            return cleanRow;
          });
        }

        try {
          await tx`INSERT INTO public.${tx(tableName)} ${tx(rows)}`;
          totalRestoredRows += rows.length;
          console.log(styleText('green', `   ✔️ ${tableName}: ${rows.length} filas restauradas exitosamente.`));
        } catch (iErr: unknown) {
          throw new Error(`Error al insertar en tabla "${tableName}": ${(iErr as Error).message}`);
        }
      }

      console.log(styleText('cyan', `\n🛡️ Asegurando privilegios de roles estándar en el esquema public...`));
      await tx`GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;`;
      await tx`GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO postgres, service_role;`;
      await tx`GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO anon, authenticated;`;
      await tx`GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO postgres, service_role;`;
      await tx`GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;`;
      await tx`GRANT ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public TO postgres, service_role;`;
      await tx`GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated;`;
      console.log(styleText('green', `   ✔️ Privilegios restablecidos correctamente.`));

      console.log(styleText('bold', styleText('green', `\n🎉 Transacción completada con éxito. ${totalRestoredRows} filas totales restauradas en [${canonicalName}].`)));
    });

    await sql.end();
  } catch (restErr: unknown) {
    console.error(styleText('red', `\n❌ Error fatal durante la restauración en [${canonicalName}]: ${(restErr as Error).message}`));
    console.error(styleText('yellow', `🔄 La transacción ha sido revertida (ROLLBACK automático). La base de datos mantiene su estado anterior.`));
    try { await sql.end(); } catch { /* ignore */ }
    process.exit(1);
  }
}

// Permitir ejecución directa
const isDirectRun = process.argv[1] && (
  process.argv[1].endsWith('restore_supabase_db.ts') ||
  process.argv[1].includes('restore_supabase_db.ts')
);

if (isDirectRun) {
  restoreSupabaseDb().catch((err) => {
    console.error(styleText('red', `❌ Error fatal: ${err.message}`));
    process.exit(1);
  });
}

/**
 * @file update_supabase_db.ts
 * @description Script automático para acceder a los servidores Supabase y gestionar la base de datos.
 * 
 * UTILIDAD:
 * 1. Consultar si existen las tablas del juego en el servidor Supabase seleccionado.
 * 2. Si no existen, crear toda la base de datos de cero ejecutando el baseline_schema.
 * 3. Si existen, aplicar los parches (migraciones) necesarios de forma incremental y segura.
 * 
 * CARACTERÍSTICAS:
 * - Permite elegir actualizar TODOS los servidores o uno en particular (--server=<perfil> o --all).
 * - Cumple con las normativas env-multi-server-parser para extraer credenciales del .env maestro.
 * - Estándares Node.js 26+ (Explicit Resource Management con 'using', prefijos node:).
 */

import fsPromises from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import postgres from 'postgres';
import { readAndParseEnv, buildDatabaseUrl } from '../lib/supabaseClient.ts';

// Optimizar ejecución en ejecuciones sucesivas
enableCompileCache();

const MIGRATIONS_DIR = path.resolve(process.cwd(), 'database/migrations');
const BASELINE_FILE = path.resolve(process.cwd(), 'database/migrations/20240416000000_baseline_schema.sql');

export async function updateSupabaseDb() {
  console.log(styleText('bold', '\n--- 🛡️ SUPABASE DATABASE MANAGER & MIGRATOR (Node.js 26+) ---'));

  const serverConfigs = await readAndParseEnv();
  const baseProfiles = Object.keys(serverConfigs);
  if (baseProfiles.length === 0) {
    console.error(styleText('red', '❌ Error: No se encontraron configuraciones de servidor (SERVER_<profile>_*) en el .env.'));
    process.exit(1);
  }

  const allAvailable = Array.from(new Set(baseProfiles.concat(Object.values(serverConfigs).map(c => c.ID).filter(Boolean) as string[])));

  // Parsear argumentos de la línea de comandos
  const args = process.argv.slice(2);
  let serverArg: string | undefined;
  const serverFlagIdx = args.findIndex(a => a === '--server');
  if (serverFlagIdx !== -1 && args[serverFlagIdx + 1] !== undefined) {
    serverArg = args[serverFlagIdx + 1];
  } else {
    serverArg = args.find(a => a.startsWith('--server='))?.split('=')[1];
  }
  const isAll = args.includes('--all');

  if (!serverArg && !isAll) {
    console.log(styleText('yellow', '⚠️  Especifica qué servidor deseas actualizar usando la bandera --server=<perfil> o --all.'));
    console.log(styleText('cyan', `Perfiles disponibles: ${allAvailable.join(', ')}`));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:update -- --server=cloud'));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:update -- --server=nas_franco'));
    console.log(styleText('gray', 'Ejemplo: npm run servers:db:update -- --all'));
    process.exit(1);
  }

  const targetProfiles = serverArg ? [serverArg] : baseProfiles;

  for (const profile of targetProfiles) {
    let conf = serverConfigs[profile];
    if (!conf) {
      const found = Object.keys(serverConfigs).find(p => serverConfigs[p]?.ID === profile);
      if (found) conf = serverConfigs[found];
    }
    if (!conf) {
      console.error(styleText('red', `❌ Error: El perfil o ID "${profile}" no existe en el archivo .env.`));
      continue;
    }

    console.log(styleText('bold', styleText('blue', `\n==================================================`)));
    console.log(styleText('bold', styleText('cyan', `🚀 INICIANDO ACTUALIZACIÓN DE BASE DE DATOS: [${profile}]`)));
    console.log(styleText('bold', styleText('blue', `==================================================`)));

    const dbUrl = buildDatabaseUrl(conf, profile);

    if (!dbUrl) {
      console.error(styleText('red', `❌ Error: No se pudo construir la URL de conexión Postgres para el perfil "${profile}".`));
      console.error(styleText('yellow', `👉 Asegúrate de tener SERVER_${profile}_POSTGRES_PASSWORD y SERVER_${profile}_SUPABASE_PUBLIC_URL en el .env`));
      continue;
    }

    const isSupabaseCloud = dbUrl.includes('.supabase.co');
    const sql = postgres(dbUrl, { ssl: isSupabaseCloud ? 'require' : false, max: 1 });

    try {
      console.log(styleText('cyan', `🔌 Conectando al servidor Postgres de [${profile}]...`));

      // 1. Consultar si existen las tablas del juego
      const tables = await sql`
        SELECT table_name 
        FROM information_schema.tables 
        WHERE table_schema = 'public' AND table_name IN ('profiles', 'system_config', '_migrations')
      `;

      const existingTables = tables.map(t => t.table_name as string);
      console.log(styleText('cyan', `📊 Tablas detectadas en el esquema public: ${existingTables.length > 0 ? existingTables.join(', ') : 'Ninguna'}`));

      let baselineContent = '';
      try {
        await using baseHandle = await fsPromises.open(BASELINE_FILE, 'r');
        baselineContent = await baseHandle.readFile({ encoding: 'utf-8' });
      } catch (baseErr: unknown) {
        console.error(styleText('red', `❌ Error al leer baseline_schema.sql: ${(baseErr as Error).message}`));
        process.exit(1);
      }

      if (existingTables.length === 0) {
        // 2. Si no existen, crear toda la base de datos de cero
        console.log(styleText('yellow', `⚠️  Base de datos limpia detectada en [${profile}]. Inicializando esquema base desde cero...`));
        console.log(styleText('gray', `📄 Ejecutando: 20240416000000_baseline_schema.sql`));

        await sql.unsafe(baselineContent);
        console.log(styleText('green', `✅ Esquema base creado exitosamente en [${profile}].`));

        await sql`CREATE TABLE IF NOT EXISTS public._migrations (id TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT NOW())`;
        await sql`INSERT INTO public._migrations (id) VALUES ('20240416000000_baseline_schema') ON CONFLICT DO NOTHING`;
      } else {
        console.log(styleText('green', `✅ Esquema base ya existe en [${profile}]. Procediendo a verificar parches...`));
        await sql`CREATE TABLE IF NOT EXISTS public._migrations (id TEXT PRIMARY KEY, applied_at TIMESTAMPTZ DEFAULT NOW())`;
      }

      // 3. Si existe, aplicar los parches necesarios
      const appliedRows = await sql`SELECT id FROM public._migrations`;
      const appliedIds = new Set(appliedRows.map(r => r.id as string));

      const files = (await fsPromises.readdir(MIGRATIONS_DIR))
        .filter(f => f.endsWith('.sql') && !f.includes('baseline_schema'))
        .sort((a, b) => a.localeCompare(b));

      let patchesApplied = 0;

      for (const filename of files) {
        const migrationId = filename.replace('.sql', '');
        if (!appliedIds.has(migrationId)) {
          console.log(styleText('cyan', `📦 Aplicando parche: ${filename}...`));
          const filePath = path.join(MIGRATIONS_DIR, filename);
          let migContent = '';
          try {
            await using migHandle = await fsPromises.open(filePath, 'r');
            migContent = await migHandle.readFile({ encoding: 'utf-8' });
          } catch (mErr: unknown) {
            console.error(styleText('red', `❌ Error al leer archivo de migración ${filename}: ${(mErr as Error).message}`));
            continue;
          }

          let sqlContent = migContent;
          // Adaptar dialecto SQLite a Postgres para manipulación de texto sobre columnas TIMESTAMPTZ y dependencias CASCADE
          sqlContent = sqlContent.replace(/created_at NOT LIKE/g, "CAST(created_at AS TEXT) NOT LIKE");
          sqlContent = sqlContent.replace(/SET created_at = REPLACE\(created_at, ' ', 'T'\) \|\| 'Z'/g, "SET created_at = CAST(REPLACE(CAST(created_at AS TEXT), ' ', 'T') || 'Z' AS TIMESTAMPTZ)");
          sqlContent = sqlContent.replace(/DROP TABLE IF EXISTS events_config;/g, "DROP TABLE IF EXISTS events_config CASCADE;");

          try {
            await sql.begin(async (tx) => {
              await tx.unsafe(sqlContent);
              await tx`INSERT INTO public._migrations (id) VALUES (${migrationId})`;
            });
            console.log(styleText('green', `   ✅ Parche ${migrationId} aplicado correctamente.`));
            patchesApplied++;
          } catch (patchErr: unknown) {
            const pMsg = patchErr instanceof Error ? patchErr.message : String(patchErr);
            if (pMsg.toLowerCase().includes('already exists') || pMsg.toLowerCase().includes('duplicate')) {
              console.log(styleText('yellow', `   ⚠️ Parche ${migrationId} ya estaba aplicado parcialmente (duplicado benigno). Registrando como completado.`));
              await sql`INSERT INTO public._migrations (id) VALUES (${migrationId}) ON CONFLICT DO NOTHING`;
              patchesApplied++;
            } else {
              throw patchErr;
            }
          }
        }
      }

      // 4. Sincronizar db_version en system_config con la migración más reciente aplicada
      const allAppliedRows = await sql`SELECT id FROM public._migrations`;
      const versions = allAppliedRows
        .map(r => parseInt((r.id as string).split('_')[0] || '0'))
        .filter(v => v > 0);
      if (versions.length > 0) {
        const maxAppliedVersion = Math.max(...versions);
        console.log(styleText('cyan', `🔄 Sincronizando db_version en system_config de [${profile}] a la versión: ${maxAppliedVersion}`));
        await sql`
          INSERT INTO public.system_config (key, value) 
          VALUES ('db_version', ${maxAppliedVersion}::jsonb) 
          ON CONFLICT (key) 
          DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
        `;
      }

      // 5. Sincronizar app_version en system_config
      let appVersion = 'v0.5.0';
      try {
        const verPath = path.resolve(process.cwd(), 'public/version.json');
        const verContent = JSON.parse(await fsPromises.readFile(verPath, 'utf-8'));
        if (verContent && verContent.version) {
          appVersion = verContent.version;
        }
      } catch (_e) {
        // Fallback
      }
      console.log(styleText('cyan', `🔄 Sincronizando app_version en system_config de [${profile}] a la versión: ${appVersion}`));
      await sql`
        INSERT INTO public.system_config (key, value) 
        VALUES ('app_version', ${appVersion}::jsonb) 
        ON CONFLICT (key) 
        DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
      `;

      if (patchesApplied === 0) {
        console.log(styleText('green', `✨ La base de datos de [${profile}] ya está completamente actualizada. No se requieren parches.`));
      } else {
        console.log(styleText('green', `✨ Proceso completado en [${profile}]: ${patchesApplied} parches aplicados exitosamente.`));
      }

    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(styleText('red', `❌ Error al conectar o migrar la base de datos de [${profile}]: ${msg}`));
      if (msg.includes('password authentication failed') || msg.includes('placeholder')) {
        console.error(styleText('yellow', `👉 Advertencia: SERVER_${profile}_POSTGRES_PASSWORD parece ser un placeholder o es incorrecta.`));
        console.error(styleText('yellow', `👉 Configura la contraseña real en el archivo .env para poder aplicar migraciones en este servidor.`));
      }
      if (msg.toLowerCase().includes('tenant or user not found')) {
        console.error(styleText('yellow', `👉 Advertencia: El servidor proxy/pooler (Supavisor) rechazó la conexión por falta de Tenant ID.`));
        console.error(styleText('yellow', `👉 Configura SERVER_${profile}_DATABASE_URL con la cadena de conexión directa (ej. puerto 5432 directo o usuario postgres.<tenant>) en .env`));
      }
    } finally {
      await sql.end();
    }
  }
}

const isDirectRun = process.argv[1] && (
  process.argv[1].endsWith('update_supabase_db.ts') ||
  process.argv[1].includes('update_supabase_db.ts')
);

if (isDirectRun) {
  updateSupabaseDb().catch((err) => {
    console.error(styleText('red', `❌ Error fatal: ${err.message}`));
    process.exit(1);
  });
}

/**
 * scripts/validate_sql_migrations.ts
 * 
 * VALIDADOR DE MIGRACIONES SQL (Node.js 26+)
 * 
 * Este script utiliza el módulo nativo 'node:sqlite' para verificar la integridad
 * sintáctica de las migraciones SQL antes de que lleguen al cliente o producción.
 * 
 * Proceso:
 * 1. Escanea 'database/migrations/'.
 * 2. Crea una base de datos SQLite en memoria.
 * 3. Traduce y ejecuta cada migración.
 * 4. Reporta errores detallados con número de línea.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { styleText, parseArgs } from 'node:util';
import { enableCompileCache } from 'node:module';
import { splitSQLStatements, translatePostgresToSqlite } from '../../src/logic/db/sqlTranslator.ts';

// Speed up execution on subsequent runs
enableCompileCache();

const MIGRATIONS_DIR = path.resolve(process.cwd(), 'database/migrations');

async function validateMigrations() {
  const { values } = parseArgs({
    options: {
      output: { type: 'string', short: 'o' },
      summary: { type: 'boolean', short: 's' }
    }
  });

  console.log(styleText('bold', '\n--- 🛡️  SQL MIGRATION VALIDATOR (Node.js 26) ---'));

  try {
    await fs.access(MIGRATIONS_DIR);
  } catch {
    console.error(styleText('red', '❌ Error: Directorio de migraciones no encontrado.'));
    process.exit(1);
  }

  // 1. Crear DB en memoria para validación (Explicit Resource Management)
  using db = new DatabaseSync(':memory:');
  db.exec("CREATE TABLE IF NOT EXISTS _migrations (id TEXT PRIMARY KEY, applied_at TEXT DEFAULT (datetime('now')))");
  console.log(styleText('green', '✅ Base de datos temporal creada con tabla de migraciones.'));

  // 2. Obtener y ordenar archivos
  const allFiles = await fs.readdir(MIGRATIONS_DIR);
  const files = allFiles
    .filter(f => f.endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));

  const translationCache = new Map<string, string>();
  const errors: string[] = [];
  const achievements: string[] = [];

  console.log(styleText('cyan', `📦 Procesando ${files.length} archivos de migración...\n`));

  for (const filename of files) {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    const content = await fs.readFile(filePath, 'utf-8');

    try {
      const statements = splitSQLStatements(content);

      for (const stmt of statements) {
        let translated = translationCache.get(stmt);
        if (translated === undefined) {
          translated = translatePostgresToSqlite(stmt);
          translationCache.set(stmt, translated);
        }

        if (translated) {
          try {
            db.exec(translated);
          } catch (sqlErr: unknown) {
            const msg = (sqlErr as Error).message.toLowerCase();
            const isDuplicate = msg.includes('already exists') || msg.includes('duplicate column');

            if (!isDuplicate) {
              throw sqlErr;
            }
          }
        }
      }
      achievements.push(`[Migración] ${filename}: VÁLIDA`);
    } catch (e: unknown) {
      errors.push(`[Migración] ${filename}: FALLÓ: ${(e as Error).message}`);
    }
  }

  console.log(`\n════════════════════════════════════`);
  console.log(`    SQL MIGRATIONS REPORT`);
  console.log(`════════════════════════════════════`);
  console.log(`📦 Archivos detectados:  ${files.length}`);
  console.log(`✅ Migraciones válidas:  ${achievements.length}`);
  console.log(`❌ Migraciones fallidas: ${errors.length}`);
  console.log(`════════════════════════════════════\n`);

  if (values.output) {
    const outputPath = path.resolve(process.cwd(), values.output as string);
    const lines = [
      `--- SQL MIGRATIONS REPORT ---`,
      `Archivos detectados:  ${files.length}`,
      `Migraciones válidas:  ${achievements.length}`,
      `Migraciones fallidas: ${errors.length}`,
      `\nLogros (${achievements.length}):`,
      ...achievements.map(a => `  - ${a}`),
      `\nErrors (${errors.length}):`,
      ...errors.map(e => `  - ${e}`)
    ];
    await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
    console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${values.output}`));
  }

  if (values.summary) {
    console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${errors.length} errores.`));
  } else {
    if (achievements.length > 0) {
      console.log(styleText('green', `🌟 MIGRACIONES VÁLIDAS (${achievements.length}):`));
      const limit = 30;
      achievements.slice(0, limit).forEach(a => console.log(`   ✅ ${a}`));
      if (achievements.length > limit) {
        console.log(styleText('cyan', `   ... y ${achievements.length - limit} migraciones más (usa -o para ver todas)`));
      }
      console.log('');
    }

    if (errors.length > 0) {
      console.log(styleText('red', `❌ ERRORES DE INTEGRIDAD DETECTADOS (${errors.length}):`));
      const limit = 30;
      errors.slice(0, limit).forEach(e => console.log(`   🚨 ${e}`));
      if (errors.length > limit) {
        console.log(styleText('cyan', `   ... y ${errors.length - limit} errores más (usa -o para ver todos)`));
      }
    } else {
      console.log(styleText('green', '✨ TODAS LAS MIGRACIONES SON VÁLIDAS PARA SQLITE.'));
    }
  }

  if (errors.length > 0) {
    process.exit(1);
  } else {
    process.exit(0);
  }
}

validateMigrations();

/**
 * @file reportUtils.ts
 * @description Utilidades compartidas para formateo de reportes y salida de scripts de validación
 * del proyecto. Evita la duplicación de lógica de generación de archivos de reporte.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';

export interface ValidationSummary {
  title: string;
  scannedMetrics: Record<string, number>;
  errors: string[];
  warnings: string[];
}

export function printConsoleHeader(title: string) {
  console.log(styleText('bold', `\n--- 🛡️  ${title} ---`));
}

export function printConsoleSummary(summary: ValidationSummary, verbose: boolean = true) {
  console.log(`\n════════════════════════════════════`);
  console.log(`    ${summary.title.toUpperCase()}`);
  console.log(`════════════════════════════════════`);
  for (const [key, value] of Object.entries(summary.scannedMetrics)) {
    console.log(`📦 ${key}: ${value}`);
  }
  console.log(`════════════════════════════════════\n`);

  if (!verbose) {
    console.log(styleText('cyan', `\n[INFO] Modo resumen activo: ${summary.errors.length} errores, ${summary.warnings.length} advertencias.`));
  } else {
    if (summary.warnings.length) {
      console.log(styleText('yellow', `⚠️  WARNINGS (${summary.warnings.length}):`));
      const limit = 30;
      summary.warnings.slice(0, limit).forEach(w => console.log(`   ${w}`));
      if (summary.warnings.length > limit) {
        console.log(styleText('cyan', `   ... y ${summary.warnings.length - limit} advertencias más (usa -o para ver todas)`));
      }
      console.log('');
    }

    if (summary.errors.length) {
      console.log(styleText('red', `❌ ERRORS (${summary.errors.length}):`));
      const limit = 30;
      summary.errors.slice(0, limit).forEach(e => console.log(`   ${e}`));
      if (summary.errors.length > limit) {
        console.log(styleText('cyan', `   ... y ${summary.errors.length - limit} errores más (usa -o para ver todos)`));
      }
      console.log('\n' + styleText('red', 'Corrige estos errores para asegurar la integridad de los datos.'));
    } else {
      console.log(styleText('green', '✅ Todos los componentes pasaron la validación con éxito!'));
    }
  }
}

export async function writeReportFile(outputPathArg: string, summary: ValidationSummary) {
  const outputPath = path.resolve(process.cwd(), outputPathArg);
  const metricLines = Object.entries(summary.scannedMetrics).map(([key, val]) => `${key}: ${val}`);

  const lines = [
    `--- ${summary.title.toUpperCase()} ---`,
    ...metricLines,
    `\nErrors (${summary.errors.length}):`,
    ...summary.errors.map(e => `  - ${e}`),
    `\nWarnings (${summary.warnings.length}):`,
    ...summary.warnings.map(w => `  - ${w}`)
  ];

  await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
  console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${outputPathArg}`));
}

/**
 * scripts/audit_project.ts
 * 
 * STABLE PROJECT AUDIT ENGINE (Node.js 26+)
 * 
 * Final Safe Version: Context-aware GPU checking.
 */

import fs from 'node:fs/promises';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import { parseArgs } from 'node:util';
import { execSync } from 'node:child_process';
import { Z_LAYERS } from '../../src/logic/constants/visuals.ts';

enableCompileCache();

const IGNORE_DIRS = new Set(['node_modules', '.git', 'dist', 'dev-dist', 'backup_legacy_code', 'public', 'docs', 'scratch', 'showdown']);
const AUDIT_EXTENSIONS = new Set(['.vue', '.scss', '.css', '.ts', '.js']);


interface AuditRule {
  regex: RegExp;
  message: string | ((match: string) => string);
  fix?: (match: string) => string;
  check?: (context: string, match: RegExpExecArray, filePath?: string) => boolean;
  severity?: 'error' | 'warning';
  fixable?: boolean;
  addImport?: string;
  maxLines?: number;
  ignorePattern?: RegExp;
}

interface Violation {
  file: string; line: number; message: string; context: string; severity: 'error' | 'warning'; fixable: boolean;
}

// Invert Z_LAYERS for lookup
const Z_VALUE_MAP = Object.fromEntries(
  Object.entries(Z_LAYERS).map(([key, value]) => [value, key])
);

// Sorted values for nearest search
const Z_SORTED_ENTRIES = Object.entries(Z_LAYERS).sort((a, b) => a[1] - b[1]);

const viewport: AuditRule = {
  regex: /\b\d+(?:\.\d+)?(vw|vh)\b/gi,
  message: (match: string) => `Unidad legacy detectada: '${match}'. Usa 'd${match.slice(-2)}' para soporte mobile dinámico.`,
  fix: (match: string) => `d${match.toLowerCase().slice(-2)}`
};


const gpuGaps: AuditRule = {
  regex: /(backdrop-filter|filter):/gi,
  message: "Filtro detectado sin 'will-change'. Considera añadir promoción de capa.",
  severity: 'error',
  check: (content: string, match: RegExpExecArray, filePath?: string) => {
    const start = Math.max(0, match.index - 500);
    const end = Math.min(content.length, match.index + 500);
    const context = content.substring(start, end);

    // 1. Check for standard disable/ignore comments in the context
    if (/audit-disable\s+gpu-gaps|will-change:\s*(skip|ignore|false)/i.test(context)) {
      return false;
    }

    // 2. Check if this is a high-density component (card, sprite, avatar, nickname, weather, list, grid, cell, row, icon, badge)
    // We analyze the surrounding text or selector for typical high-density keywords
    const beforeMatch = content.substring(start, match.index);
    const lastSemi = Math.max(beforeMatch.lastIndexOf(';'), beforeMatch.lastIndexOf('}'), beforeMatch.lastIndexOf('{'));
    const selectorText = beforeMatch.substring(lastSemi + 1).trim();

    const highDensityKeywords = /(card|item|sprite|avatar|nickname|badge|icon|grid|list|row|cell|weather|overlay|background)/i;
    if (highDensityKeywords.test(selectorText) || (filePath && highDensityKeywords.test(filePath))) {
      return false;
    }

    // 3. Only warn if the filter is dynamically animated or transitioned via CSS
    // Check if there is transition or animation property in the context that targets filter/backdrop-filter/all
    const isDynamic = /transition\s*:[^;]*(filter|backdrop-filter|all)|animation\s*:/gi.test(context);
    if (!isDynamic) {
      return false; // Static filter - does not require layer promotion
    }

    // 4. Warn if will-change is missing
    return !/(will-change|will-animate)/gi.test(context);
  },
  fixable: false 
};

const legacyDates: AuditRule = {
  regex: /new Date\(|Date\.now\(\)/g,
  message: "Uso de 'Date' detectado. Usa 'Temporal'.",
  severity: 'error',
  check: (filePath: string) => {
    const lowerPath = filePath.toLowerCase();
    const isTestOrMock = lowerPath.includes('test') || lowerPath.includes('mock');
    return !isTestOrMock;
  },
  fixable: false
};

const hardcodedTimezone: AuditRule = {
  regex: /toZonedDateTimeISO\(\s*['"]([^'"]+)['"]\s*\)|toPlainDateTime\(\s*['"]([^'"]+)['"]\s*\)|Temporal\.TimeZone\.from\(\s*['"]([^'"]+)['"]\s*\)/g,
  message: (match: string) => `Timezone hardcodeado detectado: '${match}'. Usa la variable global 'GAME_TIMEZONE' importada desde '@/logic/utils/timeUtils' para respetar la configuración del servidor.`,
  severity: 'error',
  check: (filePath: string) => {
    if (filePath.endsWith('timeUtils.ts')) return false;
    const lowerPath = filePath.toLowerCase();
    const isTestOrMock = lowerPath.includes('test') || lowerPath.includes('mock');
    return !isTestOrMock;
  },
  fixable: false
};

const nodePrefix: AuditRule = {
  regex: /import .* from ['"](fs|path|os|crypto|util|url|events|stream|child_process)['"]/g,
  message: "Import de Node sin prefijo 'node:'.",
  fix: (match: string) => match.replace(/['"](fs|path|os|crypto|util|url|events|stream|child_process)['"]/, (m) => m.slice(0, 1) + 'node:' + m.slice(1))
};

const esmExtensions: AuditRule = {
  // Match relative imports WITHOUT an extension (not .ts, .js, .json, or .vue at the end)
  regex: /import .* from ['"](\.\.[^'"]*(?<!\.[jt]s)(?<!\.vue)(?<!\.json))['"]|import .* from ['"](\.[^/][^'"]*(?<!\.[jt]s)(?<!\.vue)(?<!\.json))['"]/g,
  message: (match: string) => `Import relativo sin extensión: '${match}'. En Node.js 26+ nativo las extensiones son obligatorias.`,
  severity: 'error',
  // Fix: only add .ts when the path doesn't already end with .vue, .js, .ts, or .json
  fix: (match: string) => match.replace(/(['"])(\.\.?\/[^'"]+)(?<!\.[jt]s)(?<!\.vue)(?<!\.json)(['"])/g, '$1$2.ts$3'),
  // Only applies to pure .ts files in src/logic, scripts — NOT .vue files (handled by Vite resolver)
  check: (filePath: string) => !filePath.endsWith('.vue')
};

const tsIgnore: AuditRule = {
  regex: /\/\/\s*@ts-(ignore|nocheck|expect-error)/g,
  message: "Uso de supresión de TypeScript detectado. Prohibido por la política 'Zero-Ignore'.",
  severity: 'error',
  fix: () => '',
  fixable: true
};

const timersPromises: AuditRule = {
  regex: /new Promise\(r => setTimeout\(r, (\d+)\)\)/g,
  message: "Uso de setTimeout manual en script Node. Considera 'import { setTimeout } from \"node:timers/promises\"'.",
  // Only report in scripts/ — NEVER auto-fix via addImport (caused mass injection)
  check: (filePath: string) => filePath.includes('scripts' + path.sep) && !filePath.includes('node_modules'),
  fixable: false
  // NOTE: addImport removed intentionally — it caused spurious injection in src/ frontend files.
};

const explicitResource: AuditRule = {
  regex: /const (\w+) = (new DatabaseSync|fs\.openSync)/g,
  message: "Recurso detectado sin 'using'. Usa Explicit Resource Management (Node 26+).",
  fix: (match: string) => match.replace('const', 'using'),
  check: (filePath: string) => filePath.includes('scripts' + path.sep)
};

const manualAnimations: AuditRule = {
  regex: /@keyframes\b|\btransition\s*:/g,
  message: (match: string) => `Animación manual detectada: '${match}'. MIGRACIÓN OBLIGATORIA A GSAP: Está estrictamente PROHIBIDO borrar esta animación sin haberla migrado antes a GSAP para preservar la experiencia visual.`,
  severity: 'error',
  fixable: false
};

const manualTimersFrontend: AuditRule = {
  regex: /\b(set|clear)(Timeout|Interval)\b/g,
  message: (match: string) => `Timer de ANIMACIÓN/UI detectado: '${match}'. MIGRACIÓN OBLIGATORIA A GSAP: Prohibido en componentes UI y lógicas para gestionar flujo visual o reintentos de carga. Usa gsap.delayedCall, timelines o promesas deterministas.`,
  severity: 'error', 
  check: (content: string, _match: RegExpExecArray, filePath?: string) => {
    if (!filePath) return false;
    if (/audit-disable\s+timers/i.test(content)) return false;
    // Strictly block inside Vue SFCs under src/components/ to protect component logic
    return filePath.endsWith('.vue') && filePath.includes('src' + path.sep + 'components');
  },
  fixable: false
};

const jsonStringifyInWatch: AuditRule = {
  regex: /\bwatch\s*\(\s*(?:\(\)\s*=>\s*)?JSON\.stringify/g,
  message: "Uso de 'JSON.stringify' dentro de un watcher detectado. Serializar objetos/arrays en watchers de alta frecuencia satura la CPU. Realiza comparaciones directas por elementos o usa watchers profundos ({ deep: true }) con moderación.",
  severity: 'error',
  fixable: false
};

const intersectionObserverRoot: AuditRule = {
  regex: /new\s+IntersectionObserver\s*\(\s*[^,]+,\s*\{\s*[^}]*root\s*:\s*(?!null\b)[a-zA-Z0-9_$]/g,
  message: "Uso de 'root' dinámico o DOM en IntersectionObserver detectado. En contenedores escalados o con zoom (ej: #zoomable-content), usar un root distinto de null genera fallos de cálculo de visibilidad que apagan animaciones. Deja 'root' como 'null' (viewport) o no lo declares.",
  severity: 'warning',
  fixable: false
};

const dbInTemplates: AuditRule = {
  regex: /\b(pokemonDataProvider|DBRouter|sqlite|supabase)\b/g,
  message: "Acceso directo a Base de Datos o Data Provider detectado dentro de un bloque <template>. Está PROHIBIDO consultar datos en el render loop. Cachea los datos reactivamente con 'computed' en <script> y expón una estructura de datos lista para renderizar.",
  severity: 'error',
  fixable: false
};

const functionCallsInTemplates: AuditRule = {
  regex: /(?::[a-zA-Z0-9-]+|v-bind:[a-zA-Z0-9-]+)="([a-zA-Z0-9_$]+)\([^"]*\)"|\{\{\s*([a-zA-Z0-9_$]+)\([^}]*\)\s*\}\}/g,
  message: (match: string) => `Llamada a función/método '${match}' detectada en plantilla Vue. Está PROHIBIDO llamar a funciones que realicen consultas a bases de datos, transformaciones de array (.map/.filter) o lógica pesada en el render loop. Cachea los datos con 'computed'.`,
  severity: 'error',
  check: (_content: string, match: RegExpExecArray, filePath?: string) => {
    if (!filePath) return false;
    const funcName = match[1] || match[2];
    if (!funcName) return false;

    // Ignorar funciones seguras comunes de formato o traducción
    const safeFunctions = /^(t|i18n|translate|formatCurrency|formatNumber|class|style|typeof)$/i;
    if (safeFunctions.test(funcName)) return false;

    try {
      const fullFileContent = readFileSync(filePath, 'utf-8');
      const scriptStart = fullFileContent.indexOf('<script');
      const scriptEnd = fullFileContent.indexOf('</script>');
      if (scriptStart === -1 || scriptEnd === -1) return false;
      const scriptContent = fullFileContent.substring(scriptStart, scriptEnd);

      const funcDefRegex = new RegExp(`(?:const|let|var|function)\\s+${funcName}\\b[^;]*`, 'g');
      const defMatch = funcDefRegex.exec(scriptContent);
      if (!defMatch) return false;

      const defStart = defMatch.index;
      const defContext = scriptContent.substring(defStart, Math.min(scriptContent.length, defStart + 1000));

      const isHeavy = /\b(pokemonDataProvider|DBRouter|sqlite|supabase|getGuardianData|\.map\(|\.filter\(|\.reduce\()/i.test(defContext);
      return isHeavy;
    } catch (_e) {
      return false;
    }
  },
  fixable: false
};

const fileLength: AuditRule = {
  regex: /[\s\S]*/,
  message: () => `Archivo demasiado largo.`, // Placeholder, handled in logic
  maxLines: 500,
  ignorePattern: /\[PureVue-Ignore-Length\]/
};

const zIndexAudit: AuditRule = {
  regex: /z-index\s*:\s*(-?\d+)\b/gi,
  message: (match: string) => {
    const val = parseInt(match.match(/-?\d+/)![0]!);

    const entry = Z_VALUE_MAP[val];
    if (entry) {
      const key = entry.toLowerCase().replace(/_/g, '-');
      return `Z-Index hardcodeado detectado: '${match}'. Corresponde a Z_LAYERS.${entry}. Usa 'var(--z-${key})'.`;
    }

    // Nearest match (+/- 10)
    let nearestKey = '';
    let minDiff = 11;
    for (const [key, zVal] of Z_SORTED_ENTRIES) {
      const diff = Math.abs(val - zVal);
      if (diff < minDiff) {
        minDiff = diff;
        nearestKey = key;
      }
    }

    if (nearestKey) {
      const key = nearestKey.toLowerCase().replace(/_/g, '-');
      const offset = val - Z_LAYERS[nearestKey as keyof typeof Z_LAYERS];
      const sign = offset >= 0 ? '+' : '-';
      return `Z-Index relativo detectado: '${match}'. Cerca de Z_LAYERS.${nearestKey}. Usa 'calc(var(--z-${key}) ${sign} ${Math.abs(offset)})'.`;
    }

    return `Z-Index hardcodeado fuera de estándar: '${match}'. Define una nueva capa en 'visuals.ts' o usa una existente.`;
  },
  severity: 'error',
  fix: (match: string) => {
    const valMatch = match.match(/-?\d+/);
    if (!valMatch) return match;
    const val = parseInt(valMatch[0]);

    const entry = Z_VALUE_MAP[val];
    if (entry) {
      const key = entry.toLowerCase().replace(/_/g, '-');
      return `z-index: var(--z-${key})`;
    }

    let nearestKey = '';
    let minDiff = 11;
    for (const [key, zVal] of Z_SORTED_ENTRIES) {
      const diff = Math.abs(val - zVal);
      if (diff < minDiff) {
        minDiff = diff;
        nearestKey = key;
      }
    }

    if (nearestKey) {
      const key = nearestKey.toLowerCase().replace(/_/g, '-');
      const offset = val - Z_LAYERS[nearestKey as keyof typeof Z_LAYERS];
      const sign = offset >= 0 ? '+' : '-';
      return `z-index: calc(var(--z-${key}) ${sign} ${Math.abs(offset)})`;
    }

    return match;
  },
  fixable: true
};

const config = {
  viewport, gpuGaps, legacyDates, hardcodedTimezone, nodePrefix, esmExtensions, tsIgnore, timersPromises, explicitResource, fileLength, zIndexAudit, manualAnimations, manualTimersFrontend, jsonStringifyInWatch, intersectionObserverRoot, dbInTemplates, functionCallsInTemplates
};

async function getFilesToAudit(dir: string): Promise<string[]> {
  const files: string[] = [];
  const pattern = `**/*{${Array.from(AUDIT_EXTENSIONS).join(',')}}`;

  for await (const entry of fs.glob(pattern, { cwd: dir, exclude: (p: string) => Array.from(IGNORE_DIRS).some(d => p.includes(d)) })) {
    files.push(path.resolve(dir, entry));
  }
  return files;
}

async function auditFile(filePath: string, fix: boolean): Promise<Violation[]> {
  const violations: Violation[] = [];
  let content = await fs.readFile(filePath, 'utf-8');
  let modified = false;

  const isVue = filePath.endsWith('.vue');
  const isLogic = filePath.endsWith('.ts') || filePath.endsWith('.js');
  const isStyle = filePath.endsWith('.scss') || filePath.endsWith('.css');

  if (isLogic || isVue) {
    const tag = 'script';
    const block = isVue ? extractBlock(content, tag) : content;
    if (block) {
      const allRules: AuditRule[] = [legacyDates, config.hardcodedTimezone, nodePrefix, esmExtensions, tsIgnore, timersPromises, explicitResource, config.jsonStringifyInWatch, config.intersectionObserverRoot];
      let rules: AuditRule[] = allRules;

      // EXCEPCIÓN: Ignorar 'legacyDates' en scripts de utilidad/migración
      if (filePath.includes('scripts' + path.sep) || filePath.includes('supabase' + path.sep) || filePath.includes('audit_project.ts')) {
        rules = rules.filter(r => r !== config.legacyDates);
      }

      let newBlock = runRules(filePath, block, rules, violations, fix, isVue ? findBlockStart(content, tag) : 0);

      // Post-fix: Añadir imports necesarios si se aplicaron correcciones
      if (fix && newBlock !== block) {
        for (const rule of rules) {
          const importer = rule.addImport;
          if (importer && newBlock.includes(importer.split(' ')[1]!) && !newBlock.includes(importer)) {
            newBlock = importer + '\n' + newBlock;
          }
        }
        content = isVue ? injectBlock(content, tag, newBlock) : newBlock;
        modified = true;
      }
    }
  }

  if (isStyle || isVue) {
    const tag = 'style';
    const block = isVue ? extractBlock(content, tag) : content;
    if (block) {
      const newBlock = runRules(filePath, block, [config.viewport, config.gpuGaps, config.zIndexAudit, config.manualAnimations], violations, fix, isVue ? findBlockStart(content, tag) : 0);
      if (fix && newBlock !== block) {
        content = isVue ? injectBlock(content, tag, newBlock) : newBlock;
        modified = true;
      }
    }
  }

  if (isVue) {
    const tag = 'script';
    const block = extractBlock(content, tag);
    if (block) {
      runRules(filePath, block, [config.manualTimersFrontend], violations, fix, findBlockStart(content, tag));
    }
  }

  if (isVue) {
    const tag = 'template';
    const block = extractBlock(content, tag);
    if (block) {
      runRules(filePath, block, [config.dbInTemplates, config.functionCallsInTemplates], violations, fix, findBlockStart(content, tag));
    }
  }

  // MODULARITY AUDIT: 300/500/1000 Rule
  const isDatabaseOrMetadata = filePath.includes('src' + path.sep + 'data' + path.sep) || 
                               filePath.includes('scripts' + path.sep) ||
                               filePath.includes('supabase' + path.sep) ||
                               filePath.endsWith('DB.ts') || 
                               filePath.endsWith('Metadata.ts');

  if (!isDatabaseOrMetadata) {
    // Calcular SLOC real excluyendo comentarios y líneas vacías
    let slocCount = 0;
    let inBlockComment = false;
    let inHtmlComment = false;
    for (const line of content.split('\n')) {
      const trimmed = line.trim();
      if (trimmed === '') continue;
      if (inBlockComment) {
        if (trimmed.includes('*/')) inBlockComment = false;
        continue;
      }
      if (inHtmlComment) {
        if (trimmed.includes('-->')) inHtmlComment = false;
        continue;
      }
      if (trimmed.startsWith('//')) continue;
      if (trimmed.startsWith('/*')) {
        if (!trimmed.includes('*/')) inBlockComment = true;
        continue;
      }
      if (trimmed.startsWith('<!--')) {
        if (!trimmed.includes('-->')) inHtmlComment = true;
        continue;
      }
      slocCount++;
    }

    const hasLengthIgnore = config.fileLength.ignorePattern?.test(content);
    const isVueFile = filePath.endsWith('.vue');

    // [PureVue-Ignore-Length] is ONLY allowed for database/data files. UI files (.vue) or standard logic files cannot use it.
    const isAllowedIgnore = hasLengthIgnore && !isVueFile && (
      filePath.toLowerCase().includes('data') ||
      filePath.toLowerCase().includes('database') ||
      filePath.toLowerCase().includes('catalog') ||
      /export\s+const\s+[A-Z_]+\s*[:=]\s*(?:\[|\{)/.test(content)
    );

    if (slocCount > 1000) {
      violations.push({
        file: filePath,
        line: slocCount,
        message: `Mantenibilidad CRÍTICA: El archivo supera las 1000 líneas reales de código (SLOC: ${slocCount}). A pesar de cualquier tag de ignore, superar las 1000 líneas es un ERROR que requiere modularización obligatoria.`,
        context: `SLOC: ${slocCount}`,
        severity: 'error',
        fixable: false
      });
    } else if (slocCount > 500 && !isAllowedIgnore) {
      violations.push({
        file: filePath,
        line: slocCount,
        message: `Mantenibilidad (500/1000 Rule): El archivo tiene ${slocCount} líneas reales de código (SLOC). Supera las 500 líneas. Se recomienda fuertemente modularizar y extraer lógica a Composables (SRP).`,
        context: `SLOC: ${slocCount}`,
        severity: 'warning',
        fixable: false
      });
    }
  }

  if (fix && modified) {
    await fs.writeFile(filePath, content, 'utf-8');
  }

  return violations;
}

function isInsideComment(content: string, index: number): boolean {
  const before = content.substring(0, index);

  // Check for Block Comment /* ... */
  const lastStartBlock = before.lastIndexOf('/*');
  const lastEndBlock = before.lastIndexOf('*/');
  if (lastStartBlock > lastEndBlock) return true;

  // Check for Line Comment // ...
  const lastNewLine = before.lastIndexOf('\n');
  const lastLineComment = before.lastIndexOf('//');
  if (lastLineComment > lastNewLine) return true;

  return false;
}

function runRules(filePath: string, content: string, rules: AuditRule[], violations: Violation[], fix: boolean, offset: number): string {
  let result = content;
  for (const rule of rules) {
    const regex = new RegExp(rule.regex.source, rule.regex.flags);
    let match;
    while ((match = regex.exec(content)) !== null) {
      // 0. Skip comments to avoid false positives
      if (isInsideComment(content, match.index)) continue;

      // 1. Specialized checks
      if (rule.check) {
        if (rule === config.gpuGaps || rule === config.manualTimersFrontend) {
          if (!rule.check(content, match, filePath)) continue;
        } else {
          if (!rule.check(filePath, match)) continue;
        }
      }

      const lineNo = content.substring(0, match.index).split('\n').length + offset;
      violations.push({
        file: filePath, line: lineNo, message: typeof rule.message === 'function' ? rule.message(match[0]) : rule.message, 
        context: match[0], severity: rule.severity || 'warning', fixable: !!rule.fix
      });
    }
    const fixer = rule.fix;
    if (fix && fixer) {
      const gRegex = new RegExp(rule.regex.source, rule.regex.flags.includes('g') ? rule.regex.flags : rule.regex.flags + 'g');

      // Aplicar fix solo si pasa el check (contexto-aware)
      result = result.replace(gRegex, (match) => {
        // Necesitamos recrear el match array para el check
        const execMatch = rule.regex.exec(content);
        if (rule.check) {
          const pass = (rule === config.gpuGaps) 
            ? rule.check(content, execMatch!, filePath) 
            : rule.check(filePath, execMatch!);
          if (!pass) return match;
        }
        return fixer(match);
      });
    }
  }
  return result;
}

function extractBlock(content: string, tag: string): string | null {
  const match = content.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return match ? (match[1] ?? null) : null;
}

function findBlockStart(content: string, tag: string): number {
  const match = content.match(new RegExp(`<${tag}[^>]*>`, 'i'));
  return match ? content.substring(0, match.index!).split('\n').length : 0;
}

function injectBlock(content: string, tag: string, block: string): string {
  return content.replace(new RegExp(`(<${tag}[^>]*>)[\\s\\S]*?(<\\/${tag}>)`, 'i'), `$1${block}$2`);
}

async function checkZIndexConsistency(fix: boolean): Promise<string[]> {
  const scssPath = path.resolve(process.cwd(), 'src/styles/core/_variables.scss');
  try {
    let scssContent = await fs.readFile(scssPath, 'utf-8');
    let modified = false;
    const errors: string[] = [];

    for (const [key, value] of Object.entries(Z_LAYERS)) {
      const dashedKey = key.toLowerCase().replace(/_/g, '-');
      const varName = `--z-${dashedKey}`;
      const regex = new RegExp(`${varName}\\s*:\\s*(-?\\d+)\\b`);
      const match = scssContent.match(regex);

      if (!match) {
        errors.push(`Falta variable CSS '${varName}' (debe ser ${value})`);
        if (fix) {
          // Intentar insertar antes del cierre del bloque :root
          if (scssContent.includes(':root {')) {
             scssContent = scssContent.replace(/}\s*$/, `  ${varName}: ${value};\n}\n`);
             modified = true;
          }
        }
      } else if (parseInt(match[1]!) !== value) {
        errors.push(`Desincronización en '${varName}': TS=${value}, SCSS=${match[1]}`);
        if (fix) {
          scssContent = scssContent.replace(regex, `${varName}: ${value}`);
          modified = true;
        }
      }
    }

    if (fix && modified) {
      await fs.writeFile(scssPath, scssContent, 'utf-8');
    }
    return errors;
  } catch (e) {
    return [`Error leyendo _variables.scss: ${e}`];
  }
}

function getChangedFiles(ref: string): string[] {
  try {
    const output = execSync(`git diff --name-only ${ref}`, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'] });
    return output
      .split('\n')
      .map(f => f.trim())
      .filter(f => f !== '' && AUDIT_EXTENSIONS.has(path.extname(f)) && !Array.from(IGNORE_DIRS).some(d => f.includes(d)))
      .map(f => path.resolve(process.cwd(), f));
  } catch (_e) {
    console.log(styleText('yellow', `⚠️ No se pudo obtener la lista de archivos modificados desde git para ref: '${ref}'. Se auditará el proyecto completo.`));
    return [];
  }
}

interface FallowInstance {
  path?: string;
  file?: string;
  line?: number;
  start_line?: number;
}
interface FallowCloneGroup {
  instances: FallowInstance[];
  duplicated_tokens: number;
}
interface FallowFinding {
  path: string;
  line: number;
  cwe?: number;
  evidence?: string;
  kind?: string;
  function_name?: string;
  cognitive?: number;
  cyclomatic?: number;
}
interface FallowUnusedDep {
  package_name: string;
  path?: string;
  line?: number;
}
interface FallowUnusedExport {
  export_name: string;
  path: string;
  line?: number;
}
interface FallowUnusedFile {
  path: string;
}
interface FallowDeadCode {
  unused_dependencies?: FallowUnusedDep[];
  unused_dev_dependencies?: FallowUnusedDep[];
  unused_exports?: FallowUnusedExport[];
  unused_files?: FallowUnusedFile[];
}
interface FallowComplexity {
  findings?: FallowFinding[];
}
interface FallowAuditData {
  clone_groups?: FallowCloneGroup[];
  security_findings?: FallowFinding[];
  dead_code?: FallowDeadCode;
  complexity?: FallowComplexity;
  findings?: FallowFinding[];
  unused_dependencies?: FallowUnusedDep[];
  unused_dev_dependencies?: FallowUnusedDep[];
  unused_exports?: FallowUnusedExport[];
  unused_files?: FallowUnusedFile[];
  unused_component_props?: Array<{ path: string; line?: number; component_name: string; prop_name: string }>;
  unused_component_emits?: Array<{ path: string; line?: number; component_name: string; emit_name: string }>;
  unused_types?: Array<{ path: string; line?: number; export_name: string }>;
  unused_store_members?: Array<{ path: string; line?: number; store_name: string; member_name: string }>;
}

function runFallow(command: string, extraArgs: string[] = []): Violation[] {
  const violations: Violation[] = [];
  try {
    const args = ['--format', 'json', ...extraArgs];
    const cmd = `node ./node_modules/fallow/bin/fallow ${command} ${args.join(' ')}`;
    const stdout = execSync(cmd, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'ignore'], maxBuffer: 10 * 1024 * 1024 });
    const jsonStart = stdout.indexOf('{');
    if (jsonStart !== -1) {
      const data = JSON.parse(stdout.substring(jsonStart)) as FallowAuditData;
      violations.push(...mapFallowJson(command, data));
    }
  } catch (e: unknown) {
    const err = e as { stdout?: Buffer; message?: string; stderr?: Buffer };
    if (err.stdout) {
      const stdoutStr = err.stdout.toString('utf8');
      const jsonStart = stdoutStr.indexOf('{');
      if (jsonStart !== -1) {
        try {
          const data = JSON.parse(stdoutStr.substring(jsonStart)) as FallowAuditData;
          violations.push(...mapFallowJson(command, data));
        } catch {
          // Ignorar errores de parseo de JSON en salida de error
        }
      }
    }
    if (violations.length === 0) {
      violations.push({
        file: 'fallow',
        line: 0,
        message: `Error ejecutando fallow ${command}: ${err.message || String(e)} | Stderr: ${err.stderr || ''}`,
        context: `fallow ${command}`,
        severity: 'error',
        fixable: false
      });
    }
  }
  return violations;
}

function mapFallowJson(command: string, data: FallowAuditData): Violation[] {
  const violations: Violation[] = [];
  if (command === 'dupes') {
    const groups = data.clone_groups || [];
    for (const g of groups) {
      const instances = g.instances || [];
      if (instances.length > 0) {
        const first = instances[0];
        if (first) {
          const firstPath = first.file || first.path || '';
          const firstLine = first.start_line || first.line || 0;
          const locations = instances.slice(1).map((i) => `${i.file || i.path || ''}:${i.start_line || i.line || 0}`).join(', ');
          const isTriplicate = instances.length >= 3;
          const prefix = isTriplicate ? 'Código triplicado crítico' : 'Código duplicado crítico';
          violations.push({
            file: path.resolve(process.cwd(), firstPath),
            line: firstLine,
            message: `${prefix}: Encontradas ${instances.length} coincidencias de código idéntico. Ubicaciones: ${firstPath}:${firstLine}, ${locations}`,
            context: `${isTriplicate ? 'triplicación' : 'duplicación'} (${g.duplicated_tokens} tokens)`,
            severity: 'error',
            fixable: false
          });
        }
      }
    }
  } else if (command === 'security') {
    const findings = data.security_findings || [];
    for (const f of findings) {
      violations.push({
        file: path.resolve(process.cwd(), f.path),
        line: f.line,
        message: `Vulnerabilidad de seguridad [CWE-${f.cwe}] en ${f.path}:${f.line} -> ${f.evidence}`,
        context: f.kind || '',
        severity: 'error',
        fixable: false
      });
    }
  } else if (command === 'audit') {
    if (data.dead_code) {
      const unusedDeps = [...(data.dead_code.unused_dependencies || []), ...(data.dead_code.unused_dev_dependencies || [])];
      for (const d of unusedDeps) {
        violations.push({
          file: path.resolve(process.cwd(), d.path || 'package.json'),
          line: d.line || 1,
          message: `Sugerencia de calidad (Fallow): Dependencia no usada: '${d.package_name}'`,
          context: d.package_name,
          severity: 'warning',
          fixable: false
        });
      }
      const unusedExports = data.dead_code.unused_exports || [];
      for (const x of unusedExports) {
        violations.push({
          file: path.resolve(process.cwd(), x.path),
          line: x.line || 1,
          message: `Sugerencia de calidad (Fallow): Export no usado: '${x.export_name}'`,
          context: x.export_name,
          severity: 'warning',
          fixable: false
        });
      }
      const unusedFiles = data.dead_code.unused_files || [];
      for (const f of unusedFiles) {
        violations.push({
          file: path.resolve(process.cwd(), f.path),
          line: 1,
          message: `Sugerencia de calidad (Fallow): Archivo huérfano/no usado`,
          context: f.path,
          severity: 'warning',
          fixable: false
        });
      }
    }
    if (data.complexity && data.complexity.findings) {
      for (const f of data.complexity.findings) {
        violations.push({
          file: path.resolve(process.cwd(), f.path),
          line: f.line,
          message: `Sugerencia de complejidad (Fallow): Función '${f.function_name || ''}' alta complejidad (cognitiva: ${f.cognitive || 0}, ciclomática: ${f.cyclomatic || 0})`,
          context: f.function_name || '',
          severity: 'warning',
          fixable: false
        });
      }
    }
  } else if (command === 'dead-code') {
    const unusedDeps = [...(data.unused_dependencies || []), ...(data.unused_dev_dependencies || [])];
    for (const d of unusedDeps) {
      violations.push({
        file: path.resolve(process.cwd(), d.path || 'package.json'),
        line: d.line || 1,
        message: `Sugerencia de calidad (Fallow): Dependencia no usada: '${d.package_name}'`,
        context: d.package_name,
        severity: 'warning',
        fixable: false
      });
    }
    const unusedExports = data.unused_exports || [];
    for (const x of unusedExports) {
      violations.push({
        file: path.resolve(process.cwd(), x.path),
        line: x.line || 1,
        message: `Sugerencia de calidad (Fallow): Export no usado: '${x.export_name}'`,
        context: x.export_name,
        severity: 'warning',
        fixable: false
      });
    }
    const unusedFiles = data.unused_files || [];
    for (const f of unusedFiles) {
      violations.push({
        file: path.resolve(process.cwd(), f.path),
        line: 1,
        message: `Sugerencia de calidad (Fallow): Archivo huérfano/no usado`,
        context: f.path,
        severity: 'warning',
        fixable: false
      });
    }
    // Nuevas integraciones de Fallow
    const unusedProps = data.unused_component_props || [];
    for (const p of unusedProps) {
      violations.push({
        file: path.resolve(process.cwd(), p.path),
        line: p.line || 1,
        message: `Sugerencia de calidad (Fallow): Prop no usado en componente '${p.component_name}': '${p.prop_name}'`,
        context: p.prop_name,
        severity: 'warning',
        fixable: false
      });
    }
    const unusedEmits = data.unused_component_emits || [];
    for (const e of unusedEmits) {
      violations.push({
        file: path.resolve(process.cwd(), e.path),
        line: e.line || 1,
        message: `Sugerencia de calidad (Fallow): Emit no usado en componente '${e.component_name}': '${e.emit_name}'`,
        context: e.emit_name,
        severity: 'warning',
        fixable: false
      });
    }
    const unusedTypes = data.unused_types || [];
    for (const t of unusedTypes) {
      violations.push({
        file: path.resolve(process.cwd(), t.path),
        line: t.line || 1,
        message: `Sugerencia de calidad (Fallow): Tipo no usado: '${t.export_name}'`,
        context: t.export_name,
        severity: 'warning',
        fixable: false
      });
    }
    const unusedStoreMembers = data.unused_store_members || [];
    for (const m of unusedStoreMembers) {
      violations.push({
        file: path.resolve(process.cwd(), m.path),
        line: m.line || 1,
        message: `Sugerencia de calidad (Fallow): Miembro de store no usado en '${m.store_name}': '${m.member_name}'`,
        context: m.member_name,
        severity: 'warning',
        fixable: false
      });
    }
  } else if (command === 'health') {
    const findings = data.findings || [];
    for (const f of findings) {
      violations.push({
        file: path.resolve(process.cwd(), f.path),
        line: f.line,
        message: `Sugerencia de complejidad (Fallow): Función '${f.function_name || ''}' alta complejidad (cognitiva: ${f.cognitive || 0}, ciclomática: ${f.cyclomatic || 0})`,
        context: f.function_name || '',
        severity: 'warning',
        fixable: false
      });
    }
  }
  return violations;
}

async function checkDoxIntegrity(): Promise<Violation[]> {
  const violations: Violation[] = [];
  const rootDir = process.cwd();

  // Build set of gitignored paths by parsing .gitignore directly.
  // NOTE: 'git ls-files --others --ignored' only lists paths that EXIST on disk.
  // In CI checkouts the gitignored dirs are absent, so that set would be empty.
  // Parsing .gitignore directly works regardless of whether the paths exist.
  const gitIgnoredPaths = new Set<string>();
  try {
    const gitignoreRaw = await fs.readFile(path.join(rootDir, '.gitignore'), 'utf-8');
    for (const line of gitignoreRaw.split('\n')) {
      const trimmed = line.trim().replace(/\/$/, '');
      // Skip comments, empty lines, and glob patterns (handle only plain paths)
      if (!trimmed || trimmed.startsWith('#') || trimmed.includes('*') || trimmed.includes('?')) continue;
      gitIgnoredPaths.add(path.resolve(rootDir, trimmed));
    }
  } catch { /* no .gitignore found — skip silently */ }


  // Recursivamente busca todos los directorios del proyecto (no ignorados)
  const doxDirs: string[] = [];

  async function hasCodeFiles(dir: string): Promise<boolean> {
    try {
      const entries = await fs.readdir(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isFile()) {
          const ext = path.extname(entry.name).toLowerCase();
          if (ext === '.ts' || ext === '.vue' || ext === '.js' || ext === '.scss' || ext === '.css') {
            return true;
          }
        }
      }
    } catch {
      return false;
    }
    return false;
  }

  async function traverse(dir: string) {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    const relPath = path.relative(rootDir, dir);
    const dirName = path.basename(dir);

    // Evitar directorios ignorados
    if (IGNORE_DIRS.has(dirName) || (dirName.startsWith('.') && dirName !== '.')) {
      return;
    }

    const posixRelPath = relPath.split(path.sep).join(path.posix.sep);
    if (
      posixRelPath.includes('supabase/docker') ||
      posixRelPath === 'scripts/lib' ||
      posixRelPath.includes('test aventura')
    ) {
      return;
    }

    if (relPath !== '' && relPath !== 'src') {
      // Solo exigir AGENTS.md si el directorio contiene archivos de código
      if (await hasCodeFiles(dir)) {
        doxDirs.push(dir);
      }
    }

    for (const entry of entries) {
      if (entry.isDirectory()) {
        await traverse(path.join(dir, entry.name));
      }
    }
  }

  await traverse(rootDir);

  const doxFilesMap = new Map<string, string>();

  for (const dir of doxDirs) {
    const agentsPath = path.join(dir, 'AGENTS.md');
    try {
      const content = await fs.readFile(agentsPath, 'utf-8');
      doxFilesMap.set(dir, content);
    } catch (err) {
      violations.push({
        file: agentsPath,
        line: 1,
        message: `Falta el archivo obligatorio de documentación 'AGENTS.md' en el directorio '${path.relative(rootDir, dir)}'.`,
        context: 'AGENTS.md',
        severity: 'error',
        fixable: false
      });
    }
  }

  const rootAgentsPath = path.join(rootDir, 'AGENTS.md');
  let rootContent = '';
  try {
    rootContent = await fs.readFile(rootAgentsPath, 'utf-8');
    doxFilesMap.set(rootDir, rootContent);
  } catch (err) {
    violations.push({
      file: rootAgentsPath,
      line: 1,
      message: `Falta el archivo de documentación raíz 'AGENTS.md'.`,
      context: 'AGENTS.md',
      severity: 'error',
      fixable: false
    });
  }

  function findNearestAncestorDoxDir(dir: string): string | null {
    let current = path.dirname(dir);
    while (current !== rootDir) {
      const rel = path.relative(rootDir, current);
      if (rel !== 'src' && !IGNORE_DIRS.has(path.basename(current))) {
        return current;
      }
      current = path.dirname(current);
    }
    return rootDir;
  }

  for (const [dirPath, content] of doxFilesMap.entries()) {
    const agentsPath = path.join(dirPath, 'AGENTS.md');

    if (dirPath !== rootDir) {
      const parentDoxDir = findNearestAncestorDoxDir(dirPath);
      if (parentDoxDir) {
        const parentContent = doxFilesMap.get(parentDoxDir);
        if (parentContent) {
          const relativeChildPath = path.relative(parentDoxDir, agentsPath);
          const posixPath = relativeChildPath.split(path.sep).join(path.posix.sep);
          const cleanPath = posixPath.startsWith('./') ? posixPath.slice(2) : posixPath;
          const hasLink = parentContent.includes(cleanPath) || parentContent.includes('./' + cleanPath);

          if (!hasLink) {
            const parentFile = path.join(parentDoxDir, 'AGENTS.md');
            violations.push({
              file: parentFile,
              line: 1,
              message: `El archivo '${path.relative(rootDir, agentsPath)}' no está registrado en el índice DOX de '${path.relative(rootDir, parentFile)}'.`,
              context: cleanPath,
              severity: 'error',
              fixable: false
            });
          }
        }
      }
    }

    const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
    const lines = content.split('\n');

    for (let i = 0; i < lines.length; i++) {
      const lineText = lines[i];
      if (lineText === undefined) continue;
      let match;
      while ((match = linkRegex.exec(lineText)) !== null) {
        const label = match[1] ?? '';
        const targetUrl = (match[2] ?? '').trim();

        if (targetUrl.startsWith('http://') || targetUrl.startsWith('https://') || targetUrl.startsWith('#')) {
          continue;
        }

        if (targetUrl.startsWith('file://') || path.isAbsolute(targetUrl) || /^[a-zA-Z]:/.test(targetUrl)) {
          violations.push({
            file: agentsPath,
            line: i + 1,
            message: `Enlace absoluto o prohibido '${targetUrl}' detectado en '${label}'. Se exige el uso de rutas relativas (RULE 10).`,
            context: targetUrl,
            severity: 'error',
            fixable: false
          });
          continue;
        }

        const cleanTarget = targetUrl.split('#')[0];
        if (!cleanTarget) continue;

        const absoluteTarget = path.resolve(dirPath, cleanTarget);

        // Skip validation for paths intentionally excluded via .gitignore
        // (they exist locally but are absent in CI checkouts).
        const isGitIgnored = gitIgnoredPaths.has(absoluteTarget) ||
          [...gitIgnoredPaths].some(p => absoluteTarget.startsWith(p + path.sep));
        if (isGitIgnored) continue;

        try {
          await fs.stat(absoluteTarget);
        } catch (err) {
          violations.push({
            file: agentsPath,
            line: i + 1,
            message: `Enlace roto: '${targetUrl}' apuntando a '${cleanTarget}' no existe en el disco.`,
            context: targetUrl,
            severity: 'error',
            fixable: false
          });
        }
      }
    }
  }

  return violations;
}

async function main() {
  const { values } = parseArgs({
    options: {
      fix: { type: 'boolean', short: 'f' },
      path: { type: 'string', short: 'p', default: '.' },
      output: { type: 'string', short: 'o' },
      summary: { type: 'boolean', short: 's' },
      'changed-since': { type: 'string' },
      'errors-only': { type: 'boolean' }
    }
  });
  console.log(styleText('bold', '\n--- 🔎 POKE VICIO - INTELLIGENT AUDIT ---'));
  console.log(styleText('cyan', '💡 Info: Se puede usar "--errors-only" en todos los scripts de validación y auditoría para filtrar advertencias.'));
  console.log(styleText('cyan', '💡 Recomendación: Se aconseja utilizar "--summary" para obtener un resumen estructurado.'));

  // Consistency Check
  const syncErrors = await checkZIndexConsistency(!!values.fix);
  const syncViolations: Violation[] = [];
  if (syncErrors.length > 0) {
    console.log(styleText('magenta', `\n[SYNC] Desincronización detectada entre visuals.ts y _variables.scss:`));
    syncErrors.forEach(e => console.log(styleText('yellow', `  -> ${e}`)));
    if (!values.fix) {
      console.log(styleText('cyan', '  (Usa --fix para sincronizar automáticamente)'));
      for (const err of syncErrors) {
        syncViolations.push({
          file: path.resolve(process.cwd(), 'src/styles/core/_variables.scss'),
          line: 1,
          message: `Desincronización de z-index: ${err}`,
          context: 'z-index',
          severity: 'error',
          fixable: true
        });
      }
    }
  }

  // DOX / AGENTS.md Integrity Check
  const doxErrors = await checkDoxIntegrity();


  let files: string[] = [];
  const changedSince = values['changed-since'] as string | undefined;

  if (changedSince) {
    files = getChangedFiles(changedSince);
    console.log(styleText('cyan', `Auditando solo archivos cambiados desde: '${changedSince}' (${files.length} archivos)`));
  } else {
    files = await getFilesToAudit(path.resolve(process.cwd(), values.path as string));
  }

  let all: Violation[] = [...syncViolations, ...doxErrors];
  for (const f of files) {
    all = all.concat(await auditFile(f, !!values.fix));
  }

  // Integración de Fallow
  console.log(styleText('cyan', '\nEjecutando análisis de Fallow...'));
  if (changedSince) {
    all = all.concat(runFallow('audit', ['--changed-since', changedSince]));
    all = all.concat(runFallow('security', ['--changed-since', changedSince]));
  } else {
    all = all.concat(runFallow('dupes'));
    all = all.concat(runFallow('dupes', ['--min-occurrences', '3', '--min-lines', '10', '--min-tokens', '60']));
    all = all.concat(runFallow('security'));
    all = all.concat(runFallow('dead-code'));
    all = all.concat(runFallow('health'));
  }

  // Filtrar solo errores si la opción '--errors-only' está activa
  if (values['errors-only']) {
    all = all.filter(v => v.severity === 'error');
  }

  // Priorizar mostrar siempre primero los errores, y luego los warnings
  all.sort((a, b) => {
    if (a.severity === 'error' && b.severity !== 'error') return -1;
    if (a.severity !== 'error' && b.severity === 'error') return 1;
    return 0;
  });


  if (values.summary) {
    console.log(styleText('bold', '\n--- 📊 RESUMEN DE VIOLACIONES ---'));

    const fileGroups: Record<string, number> = {};
    const typeGroups: Record<string, number> = {};

    for (const v of all) {
      const rel = path.relative(process.cwd(), v.file);
      fileGroups[rel] = (fileGroups[rel] || 0) + 1;

      let type = 'Otros';
      if (v.message.includes('Unidad legacy')) type = 'Viewport (dvh/dvw)';
      else if (v.message.includes('will-change')) type = 'Falta will-change (GPU)';
      else if (v.message.includes('Temporal')) type = 'Uso de Date (Temporal)';
      else if (v.message.includes('prefijo')) type = 'Import de Node sin prefijo';
      else if (v.message.includes('extensión')) type = 'Import relativo sin extensión';
      else if (v.message.includes('Zero-Ignore')) type = 'TypeScript Ignore';
      else if (v.message.includes('setTimeout manual')) type = 'setTimeout manual en script';
      else if (v.message.includes('timer de ANIMACIÓN')) type = 'setTimeout/setInterval en UI';
      else if (v.message.includes('sin \'using\'')) type = 'Falta explicit resource (\'using\')';
      else if (v.message.includes('Animación manual')) type = 'Animación/Transición manual (GSAP)';
      else if (v.message.includes('Z-Index')) type = 'Z-Index fuera de estándar';
      else if (v.message.includes('archivo tiene') || v.message.includes('líneas reales')) type = 'Largo de archivo (>300/500 líneas)';
      else if (v.message.includes('Código duplicado')) type = 'Fallow: Código duplicado';
      else if (v.message.includes('Código triplicado')) type = 'Fallow: Código triplicado';
      else if (v.message.includes('Vulnerabilidad de seguridad')) type = 'Fallow: Vulnerabilidad de seguridad';
      else if (v.message.includes('Sugerencia de calidad')) type = 'Fallow: Calidad / Dead Code';
      else if (v.message.includes('Sugerencia de complejidad')) type = 'Fallow: Complejidad';
      else if (v.message.includes('AGENTS.md') || v.message.includes('DOX') || v.message.includes('Enlace')) type = 'DOX / AGENTS.md';

      typeGroups[type] = (typeGroups[type] || 0) + 1;
    }

    console.log('\nPor tipo de regla:');
    Object.entries(typeGroups)
      .sort((a, b) => b[1] - a[1])
      .forEach(([type, count]) => {
        console.log(`  - ${type}: ${count}`);
      });

    console.log('\nTop 15 archivos con más problemas:');
    Object.entries(fileGroups)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 15)
      .forEach(([file, count]) => {
        console.log(`  - ${file}: ${count} violaciones`);
      });

    console.log(`\n❌ Errores: ${all.filter(v=>v.severity==='error').length} | ⚠️ Advertencias: ${all.filter(v=>v.severity==='warning').length}`);
  } else {
    const limit = 50;
    const errors = all.filter(v => v.severity === 'error');
    const warnings = all.filter(v => v.severity === 'warning');
    const sortedAll = [...errors, ...warnings];
    const toPrint = sortedAll.slice(0, limit);
    toPrint.forEach(v => console.log(styleText(v.severity === 'error' ? 'red' : 'yellow', `[${v.severity.toUpperCase()}] ${path.relative(process.cwd(), v.file)}:${v.line} -> ${v.message} ("${v.context}")`)));
    if (all.length > limit) {
      console.log(styleText('cyan', `\n[INFO] Se muestran solo las primeras ${limit} violaciones (priorizando errores) de un total de ${all.length} para evitar saturar la terminal.`));
      console.log(styleText('cyan', `👉 Para ver el resumen consolidado por archivo y regla: npm run audit -- --summary`));
      console.log(styleText('cyan', `👉 Para exportar el reporte completo a un archivo: npm run audit -- --output=scratch/audit_report.txt`));
    }
    console.log(`\n❌ Errores: ${errors.length} | ⚠️ Advertencias: ${warnings.length}`);
  }

  if (values.fix) console.log(styleText('cyan', '✨ Correcciones aplicadas.'));

  if (values.output) {
    const outputPath = path.resolve(process.cwd(), values.output as string);
    if (outputPath.endsWith('.json')) {
      await fs.writeFile(outputPath, JSON.stringify(all, null, 2), 'utf-8');
    } else {
      const lines = all.map(v => `[${v.severity.toUpperCase()}] ${path.relative(process.cwd(), v.file)}:${v.line} -> ${v.message} ("${v.context}")`);
      await fs.writeFile(outputPath, lines.join('\n'), 'utf-8');
    }
    console.log(styleText('cyan', `\n✨ Reporte completo escrito en: ${values.output}`));
  }

  // Salir con código de error si existen violaciones con severidad de error
  if (all.some(v => v.severity === 'error')) {
    process.exit(1);
  }
}
main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal en el audit: ${err.message}`));
  process.exit(1);
});

/**
 * scripts/maintenance/audit_warnings_diff.ts
 * 
 * COMPARADOR DE ADVERTENCIAS Y ERRORES (Node.js 26+)
 * 
 * Obtiene los archivos modificados localmente comparando con 'origin/main'.
 * Analiza todo el proyecto buscando ERRORES (incluyendo eslint, vue-tsc type checking, fallow dupes, fallow security).
 * Para las ADVERTENCIAS (warnings), solo analiza y exige resolver aquellas en archivos
 * modificados que sean nuevas comparadas con 'origin/main'.
 */

import { spawnSync, execSync } from 'node:child_process';
import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';

enableCompileCache();

export interface Violation {
  file: string;
  line: number;
  message: string;
  context: string;
  severity: 'error' | 'warning';
  ruleId?: string;
  isNew?: boolean;
}

// Extensiones a auditar
const AUDIT_EXTENSIONS = new Set(['.vue', '.ts', '.js', '.scss', '.css']);

export function filterNewWarnings(
  localWarnings: Violation[],
  originWarnings: Violation[],
  originContent: string | null,
  filePath: string
): Violation[] {
  const result: Violation[] = [];

  for (const violation of localWarnings) {
    if (violation.severity !== 'warning' || violation.file !== filePath) {
      continue;
    }

    if (originContent === null) {
      // Archivo nuevo -> todas las advertencias en él son nuevas
      const copy = { ...violation, isNew: true };
      result.push(copy);
      continue;
    }

    if (violation.ruleId === 'project-audit') {
      // Para la auditoría del proyecto, verificar si el contexto exacto ya existía en origin/main
      const existed = originContent.includes(violation.context);
      const copy = { ...violation, isNew: !existed };
      result.push(copy);
    } else {
      // Para ESLint, comparar ruleId y message contra origin/main
      const existed = originWarnings.some(orig => orig.ruleId === violation.ruleId && orig.message === violation.message);
      const copy = { ...violation, isNew: !existed };
      result.push(copy);
    }
  }

  return result;
}

async function getModifiedFiles(): Promise<Set<string>> {
  try {
    // Asegurarse de tener la referencia remota actualizada
    console.log(styleText('cyan', '🔄 Sincronizando con origin/main de GitHub...'));
    execSync('git fetch origin main', { stdio: 'ignore' });

    // Obtener lista de archivos modificados, agregados o sin seguimiento comparados con origin/main
    const diffOutput = execSync('git diff --name-only origin/main', { encoding: 'utf-8' });
    const statusOutput = execSync('git status --porcelain', { encoding: 'utf-8' });

    const files = new Set<string>();

    diffOutput.split('\n').forEach(f => {
      const trimmed = f.trim();
      if (trimmed) files.add(trimmed);
    });

    statusOutput.split('\n').forEach(line => {
      if (line.length > 3) {
        const file = line.substring(3).trim();
        // Evitar archivos borrados
        if (line[0] !== 'D' && line[1] !== 'D') {
          files.add(file);
        }
      }
    });

    const filteredFiles = new Set<string>();
    for (const f of files) {
      const ext = path.extname(f).toLowerCase();
      if (AUDIT_EXTENSIONS.has(ext) && !f.includes('node_modules') && !f.startsWith('dist/') && !f.startsWith('dev-dist/') && !f.startsWith('scratch/')) {
        filteredFiles.add(f);
      }
    }
    return filteredFiles;
  } catch (error) {
    console.error(styleText('red', `❌ Error al obtener archivos modificados con git: ${(error as Error).message}`));
    return new Set();
  }
}

async function getOriginFileContent(filePath: string): Promise<string | null> {
  try {
    return execSync(`git show origin/main:${filePath}`, { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'ignore'] });
  } catch {
    // Si el archivo no existe en origin/main (es nuevo)
    return null;
  }
}

async function runProjectEslint(): Promise<Violation[]> {
  const violations: Violation[] = [];
  try {
    const eslintProc = spawnSync('npx', ['eslint', '--format', 'json', '.'], { encoding: 'utf-8', maxBuffer: 50 * 1024 * 1024 });
    const output = eslintProc.stdout ? eslintProc.stdout.trim() : '';
    if (!output) return [];

    const results = JSON.parse(output);
    for (const fileResult of results) {
      const relPath = path.relative(process.cwd(), fileResult.filePath);
      if (relPath.includes('node_modules') || relPath.startsWith('dist/') || relPath.startsWith('dev-dist/') || relPath.startsWith('scratch/')) {
        continue;
      }
      for (const msg of fileResult.messages) {
        violations.push({
          file: relPath,
          line: msg.line || 0,
          message: msg.message || '',
          context: msg.source || '',
          severity: msg.severity === 2 ? 'error' : 'warning',
          ruleId: msg.ruleId || 'eslint-rule'
        });
      }
    }
  } catch (err) {
    console.error(styleText('yellow', `⚠️ Advertencia al correr ESLint en el proyecto: ${(err as Error).message}`));
  }
  return violations;
}

async function runOriginEslint(filePath: string, content: string): Promise<Violation[]> {
  const violations: Violation[] = [];
  try {
    const eslintProc = spawnSync('npx', ['eslint', '--stdin', '--stdin-filename', filePath, '--format', 'json'], {
      input: content,
      encoding: 'utf-8',
      maxBuffer: 50 * 1024 * 1024
    });
    const output = eslintProc.stdout ? eslintProc.stdout.trim() : '';
    if (!output) return [];

    const results = JSON.parse(output);
    for (const fileResult of results) {
      for (const msg of fileResult.messages) {
        violations.push({
          file: filePath,
          line: msg.line || 0,
          message: msg.message || '',
          context: msg.source || '',
          severity: msg.severity === 2 ? 'error' : 'warning',
          ruleId: msg.ruleId || 'eslint-rule'
        });
      }
    }
  } catch {
    // Ignorar fallos de eslint en el origen
  }
  return violations;
}

async function runTypeChecking(): Promise<Violation[]> {
  const violations: Violation[] = [];
  try {
    const tscProc = spawnSync('npx', ['vue-tsc', '--noEmit'], { encoding: 'utf-8', maxBuffer: 50 * 1024 * 1024 });
    const output = tscProc.stdout ? tscProc.stdout.trim() : '';
    if (!output) return [];

    // Parsear salida estándar de tsc/vue-tsc
    // Formato común: src/components/File.vue(12,5): error TS2322: Type 'x' is not assignable...
    const lines = output.split('\n');
    for (const line of lines) {
      const match = line.match(/^([^(]+)\((\d+),(\d+)\):\s+(error\s+TS\d+):\s+(.+)$/);
      if (match) {
        const file = match[1]?.trim() || '';
        const lineNum = parseInt(match[2] || '0', 10);
        const code = match[4] || '';
        const message = match[5] || '';
        violations.push({
          file: path.relative(process.cwd(), file),
          line: lineNum,
          message: `${code}: ${message}`,
          context: 'typescript',
          severity: 'error',
          ruleId: 'typescript-tsc'
        });
      } else if (line.includes('error TS')) {
        violations.push({
          file: 'tsconfig.json',
          line: 0,
          message: line.trim(),
          context: 'typescript',
          severity: 'error',
          ruleId: 'typescript-tsc'
        });
      }
    }
  } catch (err) {
    console.error(styleText('yellow', `⚠️ Advertencia al correr vue-tsc: ${(err as Error).message}`));
  }
  return violations;
}

async function runFallowDupes(): Promise<Violation[]> {
  const violations: Violation[] = [];
  try {
    const dupesProc = spawnSync('npx', ['fallow', 'dupes', '--format', 'json'], { encoding: 'utf-8', maxBuffer: 50 * 1024 * 1024 });
    const output = dupesProc.stdout ? dupesProc.stdout.trim() : '';
    if (!output) return [];

    const jsonStart = output.indexOf('{');
    if (jsonStart !== -1) {
      const data = JSON.parse(output.substring(jsonStart));
      const groups = data.clone_groups || [];
      for (const g of groups) {
        const instances = g.instances || [];
        if (instances.length > 0) {
          const first = instances[0];
          if (first) {
            const firstPath = first.file || first.path || '';
            const firstLine = first.start_line || first.line || 0;
            const locations = instances.slice(1).map((i: { file?: string; path?: string; start_line?: number; line?: number }) => `${i.file || i.path || ''}:${i.start_line || i.line || 0}`).join(', ');
            const isTriplicate = instances.length >= 3;
            const prefix = isTriplicate ? 'Código triplicado crítico' : 'Código duplicado crítico';
            violations.push({
              file: path.relative(process.cwd(), firstPath),
              line: firstLine,
              message: `${prefix}: Encontradas ${instances.length} coincidencias de código idéntico. Ubicaciones: ${firstPath}:${firstLine}, ${locations}`,
              context: `${isTriplicate ? 'triplicación' : 'duplicación'} (${g.duplicated_tokens} tokens)`,
              severity: 'error',
              ruleId: 'fallow-dupes'
            });
          }
        }
      }
    }
  } catch (err) {
    console.error(styleText('yellow', `⚠️ Advertencia al correr fallow dupes: ${(err as Error).message}`));
  }
  return violations;
}

async function runFallowSecurity(): Promise<Violation[]> {
  const violations: Violation[] = [];
  try {
    const secProc = spawnSync('npx', ['fallow', 'security', '--format', 'json'], { encoding: 'utf-8', maxBuffer: 50 * 1024 * 1024 });
    const output = secProc.stdout ? secProc.stdout.trim() : '';
    if (!output) return [];

    const jsonStart = output.indexOf('{');
    if (jsonStart !== -1) {
      const data = JSON.parse(output.substring(jsonStart));
      const findings = data.security_findings || [];
      for (const f of findings) {
        violations.push({
          file: path.relative(process.cwd(), f.path),
          line: f.line,
          message: `Vulnerabilidad de seguridad [CWE-${f.cwe}] en ${f.path}:${f.line} -> ${f.evidence}`,
          context: f.kind || '',
          severity: 'error',
          ruleId: 'fallow-security'
        });
      }
    }
  } catch (err) {
    console.error(styleText('yellow', `⚠️ Advertencia al correr fallow security: ${(err as Error).message}`));
  }
  return violations;
}

